(function () {
window.AINOW = window.AINOW || {};
var __exports = AINOW['data/data-sustainability'] = AINOW['data/data-sustainability'] || {};

const sustainabilityPrompts = [

  {"id":"sus-1","title":"Scope 3 Category 11 Measurement Plan","prompt":"You are the Head of Sustainability at a 3,000-employee European FMCG company with €800M in revenue, committed to Science-Based Targets (SBTi) for net zero by 2040. Your Scope 1 and 2 emissions are measured at 12,400 tCO2e per year, but Scope 3 Category 11 (use of sold products) is estimated at 340,000 tCO2e and has never been rigorously quantified. Using the GHG Protocol Product Standard methodology, design a 90-day measurement plan to calculate Category 11 emissions with ±15% accuracy. Specify: (1) which product lines to prioritise using revenue-weighted materiality, (2) what activity data to collect from retail partners, (3) how to build consumer-use emission factors across your product portfolio, and (4) how to present findings to the SBTi validation team. Output as a structured project plan with milestones, data requirements, and a Category 11 inventory template.","tags":["scope-3","ghg-protocol","SBTi","carbon-accounting","emissions"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":true},

  {"id":"sus-2","title":"Fleet Electrification Board Business Case","prompt":"You are the Sustainability Director at a UK logistics company operating 420 diesel HGVs with average annual mileage of 85,000 km per vehicle, generating 18,200 tCO2e in Scope 1 emissions annually. You need to build a Board-ready business case for electrifying 30% of the fleet by 2027 to meet your CDP Science-Based Target commitment. Structure your analysis around: (1) total cost of ownership comparison between diesel and battery-electric vehicles over a 7-year asset life, factoring in UK OZEV grants and current grid electricity prices, (2) depot charging infrastructure capital requirements and grid connection timelines, (3) Scope 1 emission reduction in tCO2e and percentage progress toward your SBTi near-term target, and (4) residual value risk of diesel assets under UK Net Zero Transport policy trajectory. Produce a one-page executive summary, a detailed assumptions register, and flag the top three financial risks.","tags":["scope-1","fleet","electrification","SBTi","carbon-accounting"],"author":"AINOW","created":"2024-02-15T10:05:00Z","featured":false},

  {"id":"sus-3","title":"Market-Based vs Location-Based Scope 2 Audit","prompt":"You are the Energy and Carbon Manager at a global semiconductor manufacturer with 14 production sites across Taiwan, Germany, and the United States, consuming 2.1 TWh of electricity annually. Your CFO has asked why your market-based Scope 2 figure (67,000 tCO2e) differs so significantly from your location-based figure (189,000 tCO2e) and whether the difference is defensible under CDP reporting rules. Write a technical briefing that: (1) explains the GHG Protocol Scope 2 Guidance dual-reporting requirement and what each method represents, (2) audits which of your 14 sites use contractual instruments — EACs, PPAs, green tariffs — that qualify under CDP scoring criteria, (3) identifies sites where residual mix emission factors must be applied instead of supplier-specific rates, and (4) recommends whether to procure additional Energy Attribute Certificates to close the gap before your CDP submission deadline. Format as a four-section technical memo with a site-by-site compliance table appended.","tags":["scope-2","CDP","energy-attribute-certificates","GHG-protocol","reporting"],"author":"AINOW","created":"2024-02-15T10:10:00Z","featured":false},

  {"id":"sus-4","title":"Internal Carbon Price Capital Allocation Model","prompt":"You are the CFO of a 1,800-employee Dutch chemical company with annual revenues of €1.2B and a Board-approved internal carbon price of €75/tCO2e, currently unapplied in capital allocation decisions. Three major capex proposals are on the table: a new gas-fired steam cracker (€45M, 20-year life, 8,200 tCO2e/year), a biomass boiler retrofit (€12M, saving 3,100 tCO2e/year), and a plant-level solar PV array (€8M, saving 1,400 tCO2e/year). Remodel each project's NPV and IRR by applying the €75/tCO2e shadow price across the projected operational life, using a 7% discount rate and a carbon price escalation of 5% per year in line with EU ETS forward curves. Show how the ranking of projects changes from a pure financial basis to a carbon-adjusted basis. Produce a decision memo with a three-row comparison table and a recommendation given the company's 2030 Scope 1 reduction target of -46%.","tags":["internal-carbon-price","capex","EU-ETS","carbon-accounting","finance"],"author":"AINOW","created":"2024-02-15T10:15:00Z","featured":false},

  {"id":"sus-5","title":"Scope 3 Spend-Based to Hybrid Method Transition","prompt":"You are the Sustainability Analyst at a €600M German automotive Tier-1 supplier. Your current Scope 3 Category 1 inventory uses spend-based emission factors from Exiobase, producing an estimate of 520,000 tCO2e. Your SBTi validation team has flagged that spend-based methodology is no longer acceptable for categories exceeding 40% of total Scope 3 emissions and has asked you to transition to a hybrid method for your top 20 material suppliers, who together represent 65% of Category 1 spend. Design the transition: (1) rank your top 20 suppliers by spend-weighted emission intensity using current data, (2) draft a supplier data request template aligned with the CDP Supply Chain questionnaire asking for primary activity data and emission factors, (3) specify how to blend supplier-specific data with spend-based residuals for non-responding suppliers, and (4) quantify the expected reduction in inventory uncertainty as a percentage. Output as a project timeline, a supplier engagement letter template, and an updated methodology note for your GHG inventory.","tags":["scope-3","purchased-goods","supplier-engagement","GHG-protocol","SBTi"],"author":"AINOW","created":"2024-02-15T10:20:00Z","featured":false},

  {"id":"sus-6","title":"Carbon Credit Procurement Policy","prompt":"You are the Net Zero Programme Manager at a 500-employee UK professional services firm with 11,200 tCO2e of residual emissions after a 42% absolute reduction since 2019. Your CEO has committed to net zero by 2030 using carbon credits for residual emissions, but your legal team has flagged reputational risk after recent greenwashing litigation against comparable firms. Write a carbon credit procurement policy that: (1) defines acceptable standards — Gold Standard, Verra VCS with CCB label, Jurisdictional REDD+ — and excludes lower-quality voluntary credits, (2) sets minimum quality thresholds requiring additionality verification, permanence risk buffer pools, and independent third-party verification, (3) restricts claims language to 'carbon contribution' rather than 'carbon neutral' in line with ISO 14068 and the SBTi's stance on neutralization claims, and (4) establishes a maximum percentage of the net zero target that credits can cover aligned with SBTi's 10% rule for beyond-value-chain mitigation. Produce a two-page policy document with a credit evaluation scorecard appended.","tags":["carbon-offsets","net-zero","ISO-14068","SBTi","greenwashing"],"author":"AINOW","created":"2024-02-15T10:25:00Z","featured":false},

  {"id":"sus-7","title":"Absolute vs Intensity Target Strategic Comparison","prompt":"You are the Head of Sustainability at a rapidly growing Indian IT services company with 28,000 employees, revenues of ₹42B, and current total GHG emissions of 95,000 tCO2e. Your Board is debating whether to commit to an absolute Scope 1+2 reduction of -50% by 2030 (SBTi-aligned) or an intensity-based target of -35% tCO2e per ₹1M revenue, arguing the latter is more appropriate given projected 15% annual revenue growth. Prepare a briefing that: (1) models both target trajectories through 2030 under three growth scenarios — 8%, 15%, and 22% annual revenue CAGR — showing absolute emissions under each, (2) explains SBTi's position on when intensity targets are acceptable for the services sector, (3) assesses how each target type will be scored under CDP's 2024 methodology and rated by MSCI and Sustainalytics, and (4) recommends which structure best balances ambition, credibility, and business flexibility. Format as a Board briefing paper with scenario modelling tables.","tags":["SBTi","emissions-targets","CDP","ESG-ratings","carbon-accounting"],"author":"AINOW","created":"2024-02-15T10:30:00Z","featured":false},

  {"id":"sus-8","title":"Fugitive Methane Emissions Measurement Programme","prompt":"You are the Environmental Compliance Manager at a mid-sized Australian natural gas distribution company operating 4,200 km of pipeline, with fugitive emissions currently estimated at 38,000 tCO2e using default NGER emission factors. A recent academic study suggests actual methane leakage may be 2.3x higher based on aerial measurement campaigns on comparable networks. Design a direct measurement programme: (1) specify the technology mix — optical gas imaging cameras, ultra-sensitive methane sniffers, and aerial surveys with GHGSat satellite data — and cost per kilometre of pipeline, (2) develop a stratified sampling protocol prioritising high-risk segments by age, material, and pressure rating, (3) estimate the programme budget for a 12-month pilot covering 800 km, and (4) outline the reporting transition from NGER default factors to measured data including regulatory notification requirements. Output as a measurement programme proposal with a budget breakdown table and a risk-ranked pipeline segment matrix.","tags":["fugitive-emissions","methane","scope-1","measurement","NGER"],"author":"AINOW","created":"2024-02-15T10:35:00Z","featured":false},

  {"id":"sus-9","title":"Carbon Accounting Software RFP and Vendor Evaluation","prompt":"You are the Sustainability Operations Lead at a 12,000-employee US retail company with operations across 38 states, replacing your Excel-based GHG inventory with dedicated carbon accounting software. You have shortlisted Watershed, Persefoni, and Salesforce Net Zero Cloud. Your requirements include full Scope 1/2/3 coverage, automated utility bill ingestion via API, a supplier engagement portal for Category 1 and 4 data collection, audit trail for external assurance, PCAF alignment for your captive finance subsidiary, and SAP S/4HANA integration. Produce a structured vendor evaluation framework with: (1) a weighted scoring matrix across 12 criteria reflecting your requirements, (2) five targeted RFP questions to ask each vendor, (3) a data migration risk assessment covering three years of historical GHG data, and (4) a total cost of ownership model for a 3-year contract including implementation, licensing, and internal resource costs. Format as a complete RFP evaluation document ready for procurement.","tags":["carbon-software","Watershed","Persefoni","Salesforce-Net-Zero-Cloud","carbon-accounting"],"author":"AINOW","created":"2024-02-15T10:40:00Z","featured":false},

  {"id":"sus-10","title":"SBTi Validation Submission Preparation Checklist","prompt":"You are the Climate Strategy Manager at a €1.4B Norwegian salmon aquaculture company preparing your first SBTi target validation submission. Your proposed targets are: Scope 1+2 absolute reduction of -50% by 2030 versus a 2021 base year (from 78,000 tCO2e to 39,000 tCO2e), and Scope 3 absolute reduction of -30% by 2030 for Categories 1, 3, and 11 (from 410,000 tCO2e to 287,000 tCO2e). Walk through the SBTi validation checklist: (1) verify base year emissions meet GHG Protocol Corporate Standard completeness and accuracy requirements, (2) confirm near-term targets meet the 1.5°C-aligned trajectory using the Absolute Contraction Approach, (3) verify Scope 3 target covers the required minimum percentage of total Scope 3 emissions, (4) review target boundary documentation against SBTi Target Validation Protocol v2.0, and (5) draft the one-page target statement in SBTi's required format. Output as an annotated validation checklist with a pass/fail assessment per criterion and a prioritised remediation action list.","tags":["SBTi","target-validation","GHG-protocol","net-zero","scope-3"],"author":"AINOW","created":"2024-02-15T10:45:00Z","featured":false},

  {"id":"sus-11","title":"CSRD Double Materiality Assessment Design","prompt":"You are the Head of ESG Reporting at a €2.1B Italian fashion retail group with 8,500 employees, 320 stores across Europe, and a manufacturing supply chain in Turkey and Bangladesh. You are preparing your first CSRD-compliant sustainability statement for financial year 2025. Conduct a double materiality assessment following EFRAG guidance: (1) map all relevant ESRS topics — E1 through E5, S1 through S4, G1 — against your value chain, identifying which are material from both an impact materiality perspective and a financial materiality perspective, (2) describe the stakeholder engagement process required to validate materiality conclusions, including which groups to consult and the documentation standard, (3) identify your top five material topics with a brief rationale for each, and (4) flag ESRS datapoints subject to phase-in provisions under the CSRD delegated acts. Produce a double materiality matrix, a stakeholder consultation log template, and a disclosure gap analysis table. [Describe your organization and current sustainability situation]","tags":["CSRD","ESRS","double-materiality","ESG-reporting","EU"],"author":"AINOW","created":"2024-02-15T10:50:00Z","featured":true},

  {"id":"sus-12","title":"TCFD Climate Risk Disclosure for a Property Portfolio","prompt":"You are the Chief Risk Officer at a FTSE 250 UK commercial real estate investment trust with a £3.2B portfolio across 47 office and retail assets. The UK FCA requires TCFD-aligned disclosures in your annual report. Produce a TCFD disclosure structure covering all four pillars: (1) Governance — Board committee structure for climate oversight and integration of climate risk into executive remuneration, (2) Strategy — scenario analysis using RCP 4.5 and RCP 8.5 pathways to 2050, identifying the top three physical risks (flooding, heat stress, subsidence) and transition risks (EPC minimum requirements, carbon pricing, stranded asset risk) with asset-level materiality flags, (3) Risk Management — integration of climate risks into your enterprise risk management framework including risk appetite statements and escalation thresholds, and (4) Metrics and Targets — the 12 TCFD-recommended metrics including Scope 1/2/3 emissions, CRREM pathway alignment, and percentage of portfolio with EPC ratings below C. Format as a draft annual report section with cross-references to financial statement line items.","tags":["TCFD","climate-risk","real-estate","scenario-analysis","REIT"],"author":"AINOW","created":"2024-02-15T10:55:00Z","featured":false},

  {"id":"sus-13","title":"GRI Standards Pre-Assurance Compliance Audit","prompt":"You are the Sustainability Reporting Manager at a 6,200-employee South African mining company preparing your annual GRI Standards 2021 sustainability report for external assurance. Review your draft report against GRI requirements: (1) verify all GRI Universal Standards disclosures are present — GRI 2 General Disclosures and GRI 3 Material Topics — with specific attention to GRI 2-14 (role of the highest governance body) and GRI 2-29 (stakeholder engagement approach), (2) for each of your five material topics — water use, biodiversity, occupational health and safety, economic impacts on local communities, and anti-corruption — confirm topic standard disclosures are complete including management approach narrative and quantitative disclosures, (3) identify disclosures where you have applied GRI omission exemptions and assess whether these are defensible, and (4) prepare a GRI content index in the required tabular format. Output as an audit findings report with RAG status for each required disclosure and a prioritised remediation list. [Paste your current sustainability report or ESG disclosure]","tags":["GRI","sustainability-reporting","assurance","mining","compliance"],"author":"AINOW","created":"2024-02-15T11:00:00Z","featured":false},

  {"id":"sus-14","title":"CDP Climate A-Score Gap Analysis","prompt":"You are the Climate Programme Director at a €900M Belgian specialty chemicals company that scored B on CDP Climate last year and wants to achieve an A score. A-score requires leadership-level responses across governance, risk, targets, and emissions data. Conduct a gap analysis between your current B-score responses and CDP's 2024 A-score criteria: (1) identify the specific question modules where you lost points — typically governance (C1), risks and opportunities (C2), business strategy (C3), targets (C4), and verification (C10) — and specify exactly what additional disclosure is required for each, (2) design an internal data collection programme to gather missing information, including which business units must contribute and by what deadline, (3) draft improved responses for your two weakest modules using CDP's scoring guidance, and (4) build a 12-month CDP improvement roadmap with quarterly milestones. Format as a gap analysis table, two draft improved CDP response sections, and a Gantt-chart roadmap. [Paste your current sustainability report or ESG disclosure]","tags":["CDP","A-score","climate-disclosure","gap-analysis","governance"],"author":"AINOW","created":"2024-02-15T11:05:00Z","featured":false},

  {"id":"sus-15","title":"Integrated Report Design Using Six Capitals","prompt":"You are the Head of Corporate Reporting at a JSE-listed South African financial services group with R180B in assets under management, subject to the King IV Corporate Governance Code and the IIRC Integrated Reporting Framework. Your Board has decided to produce a full Integrated Report replacing separate annual financial and sustainability reports. Design the report structure: (1) map your value creation story across the six capitals — financial, manufactured, intellectual, human, social and relationship, natural — quantifying key inputs, activities, outputs, and outcomes for each, (2) identify connectivity points between financial performance (ROE, cost-to-income ratio) and non-financial value drivers (employee engagement scores, community investment, carbon emissions per R1M revenue), (3) design the materiality determination process following the IIRC materiality principle and SASB Financial sector standards, and (4) recommend the governance structure for the integrated report including assurance scope and Board sign-off process. Produce a report outline with section-by-section content specifications and a capitals dashboard template.","tags":["integrated-reporting","IIRC","King-IV","six-capitals","SASB"],"author":"AINOW","created":"2024-02-15T11:10:00Z","featured":false},

  {"id":"sus-16","title":"SEC Climate Disclosure 10-K Readiness Assessment","prompt":"You are the VP of Investor Relations and ESG at a NASDAQ-listed US apparel company with $2.4B in revenues, 14,000 employees, and operations in 22 countries. The SEC's climate disclosure rules require disclosure of material climate-related risks and Scope 1 and 2 emissions in annual Form 10-K filings. Conduct a readiness assessment: (1) perform a materiality determination for climate-related risks under the SEC's definition, distinguishing between physical risks affecting Asia-Pacific manufacturing and transition risks affecting US retail operations, (2) assess your current GHG inventory against the SEC's Scope 1 and 2 disclosure requirement and evaluate whether Scope 3 supply chain emissions are likely to be deemed material, (3) review your disclosure controls and procedures to determine whether your GHG data collection process meets the standard required for 10-K inclusion including the role of your disclosure committee, and (4) draft the climate risk factor language for your 10-K in SEC plain English style. Output as a readiness scorecard, draft 10-K risk factor language, and a 6-month implementation roadmap.","tags":["SEC","climate-disclosure","10-K","US-regulation","ESG-reporting"],"author":"AINOW","created":"2024-02-15T11:15:00Z","featured":false},

  {"id":"sus-17","title":"CSRD Assurance Preparation Playbook","prompt":"You are the Sustainability Controller at a €3.5B Danish pharmaceutical company preparing for limited assurance on your sustainability data for the first time under CSRD for the 2025 reporting year. Your external auditor will conduct the engagement under ISAE 3000. Prepare your organisation: (1) map the ESRS datapoints subject to assurance, identifying which come from automated data systems versus manual collection processes, (2) conduct a pre-assurance internal control review for your top five highest-risk datapoints — Scope 1 and 2 emissions, waste to landfill, employee injury rate, gender pay gap, and anti-bribery training completion — documenting the control owner, control type, and evidence trail, (3) identify the three most likely findings your auditors will raise based on common industry issues and draft management responses, and (4) build a data room structure for the assurance engagement with a document checklist. Format as an assurance preparation playbook with an internal controls register template and a data room index.","tags":["assurance","CSRD","ISAE-3000","internal-controls","ESG-reporting"],"author":"AINOW","created":"2024-02-15T11:20:00Z","featured":false},

  {"id":"sus-18","title":"SASB Technology Sector Disclosure Mapping","prompt":"You are the ESG Disclosure Lead at a US-listed enterprise software company with $5.1B in annual recurring revenue, 19,000 employees, and data centres in six countries consuming 890 GWh of electricity annually. Institutional investors including BlackRock and Vanguard have requested SASB-aligned disclosure in your annual proxy statement. Map your existing disclosures to the SASB Software and IT Services standard: (1) identify all 11 SASB disclosure topics for your subsector — including data privacy, data security, workforce diversity, and environmental footprint of hardware infrastructure — and assess your current disclosure quality as complete, partial, or missing, (2) for the three topics with weakest disclosure, draft improved responses with specific metrics in SASB's required units such as MWh, percentage renewable, and number of users affected by data breaches, (3) calculate your SASB environmental footprint metrics — total energy consumed, percentage grid electricity, percentage renewable, total water withdrawn — for your most recent fiscal year, and (4) design a SASB content index table for your proxy statement. Output as a gap analysis table and a draft SASB content index.","tags":["SASB","technology","ESG-disclosure","proxy","institutional-investors"],"author":"AINOW","created":"2024-02-15T11:25:00Z","featured":false},

  {"id":"sus-19","title":"EU Green Claims Directive Legal Audit","prompt":"You are the Chief Sustainability Officer at a €1.8B French consumer goods company with 23 products currently marketed with environmental claims including 'carbon neutral', 'eco-friendly', 'sustainable', 'net zero', and 'made with recycled materials'. Following the EU Green Claims Directive proposal and enforcement actions by French DGCCRF, your Legal Director has asked for an urgent audit. Conduct the audit: (1) for each of the five claim types, assess compliance against EU Green Claims Directive substantiation requirements — is there a Life Cycle Assessment, third-party verification, or accredited certification underpinning each claim? (2) identify which claims carry the highest risk under the French loi anti-gaspillage and the EU Unfair Commercial Practices Directive, ranking them by litigation and regulatory risk, (3) for each high-risk claim, draft a remediation option — withdraw, substantiate, or replace with compliant alternative wording, and (4) design a pre-launch green claims review process for future marketing copy. Format as a legal audit report with a claims risk register and a remediation action plan.","tags":["greenwashing","EU-Green-Claims-Directive","marketing","legal","consumer-goods"],"author":"AINOW","created":"2024-02-15T11:30:00Z","featured":false},

  {"id":"sus-20","title":"Responsible Investment Report Narrative Writing","prompt":"You are the Head of Communications at a Canadian pension fund with C$95B in assets under management, publishing your first standalone Responsible Investment Report. Your investment team has provided raw data: 38% of AUM in Paris-Agreement-aligned assets, C$4.2B in green bonds held, carbon footprint of listed equity portfolio at 142 tCO2e per C$1M invested (down from 168 the prior year), and active engagement with 47 portfolio companies on climate governance. Transform this data into a compelling, credible, and TCFD-aligned public narrative: (1) write an opening CEO letter (400 words) that acknowledges the gap between current portfolio alignment and net zero and avoids vague language that could be characterised as greenwashing, (2) draft the climate risk and opportunity section (600 words) using the four TCFD pillars as structure, (3) write the engagement and stewardship section (400 words) highlighting three specific company engagements with measurable outcomes, and (4) draft three data visualisation captions that translate complex GHG metrics into plain language for pension beneficiaries. Format as draft report copy ready for design layout. [Paste your current sustainability report or ESG disclosure]","tags":["sustainability-report","TCFD","pension-fund","narrative","stakeholder-communication"],"author":"AINOW","created":"2024-02-15T11:35:00Z","featured":false},

  {"id":"sus-21","title":"Product-as-a-Service Transition Business Case","prompt":"You are the Chief Innovation Officer at a €450M Dutch office furniture manufacturer selling 280,000 chairs and 95,000 desks annually in a linear take-make-waste model. Your largest B2B customers — four major Dutch banks and two government ministries — have asked for a Product-as-a-Service leasing model as part of their circular procurement policies. Design the PaaS transition: (1) model the revenue and margin implications of shifting 30% of chair sales to a monthly leasing model (current average selling price €380, target lease price €12/month over 5 years), including the working capital impact and balance sheet treatment under IFRS 16, (2) design take-back and refurbishment logistics including reverse logistics network, refurbishment cost per unit, and residual value assumptions at end-of-lease, (3) specify the product design changes required to make your best-selling chair 95% disassemblable for component-level remanufacturing, including material passports compliant with the EU Ecodesign for Sustainable Products Regulation, and (4) calculate circular economy metric improvements: tonnes of virgin material avoided per year and percentage reduction in product carbon footprint. Output as a business case with a P&L model and a product design specification brief.","tags":["circular-economy","product-as-a-service","PaaS","Ecodesign","business-model"],"author":"AINOW","created":"2024-02-15T11:40:00Z","featured":false},

  {"id":"sus-22","title":"Construction Waste Circular Economy Programme","prompt":"You are the Sustainability Director at a UK house builder constructing 3,800 homes per year and generating an estimated 42,000 tonnes of construction and demolition waste annually, of which only 67% is currently diverted from landfill. Your target under the UK Waste Resources Action Programme is 95% diversion by 2027. Design a waste minimisation and circular economy programme: (1) conduct a waste stream analysis of your top five waste categories by tonnage — concrete, timber, plasterboard, packaging, and excavation spoil — with current disposal routes and costs per tonne, (2) for each category, identify circular economy interventions including on-site sorting, supplier take-back agreements, waste exchange platforms, and design-stage waste prevention, with estimated diversion tonnage and cost or saving per tonne, (3) design a digital waste tracking system using electronic waste transfer notes and real-time site dashboards, and (4) calculate the business case: total current disposal cost versus circular programme cost, net saving, and tCO2e avoided through reduced virgin material consumption. Format as a programme business case with a waste stream analysis table and an implementation timeline.","tags":["circular-economy","construction","waste-diversion","UK","resource-efficiency"],"author":"AINOW","created":"2024-02-15T11:45:00Z","featured":false},

  {"id":"sus-23","title":"Textile Take-Back and Reverse Logistics Design","prompt":"You are the Head of Sustainability at a Swedish fashion retailer with 680 stores across 34 countries and 1.2 billion garments sold annually. Your incoming EU Textiles Strategy obligations require producer responsibility for end-of-life textiles from 2025. Design an in-store take-back and reverse logistics programme: (1) model collection logistics for a network of in-store garment collection bins covering all 680 stores, including collection frequency, transport costs per tonne, and consolidation hub locations, (2) segment collected garments into four streams — reuse for direct resale via your secondhand channel, upcycling into new products, recycling via fibre-to-fibre mechanical or chemical recycling partners, and downcycling into insulation — with target allocation percentages and contracted partner requirements, (3) calculate the producer responsibility fee per garment sold needed to fund the programme at full scale using a €0.08/garment baseline cost estimate, and (4) design customer-facing communication including store signage and in-app messaging that avoids unsubstantiated recyclability claims. Output as a programme design document with a logistics cost model and a customer communication draft.","tags":["circular-economy","textiles","take-back","reverse-logistics","EU-regulation"],"author":"AINOW","created":"2024-02-15T11:50:00Z","featured":false},

  {"id":"sus-24","title":"EU Packaging and Packaging Waste Regulation Compliance Roadmap","prompt":"You are the Packaging Sustainability Manager at a €700M German food and beverage company generating 18,400 tonnes of primary and secondary packaging waste per year. You are subject to the German Verpackungsgesetz and the incoming EU Packaging and Packaging Waste Regulation, including mandatory recycled content minimums of 30% for plastic packaging by 2030 and elimination of unnecessary packaging formats. Develop a compliance roadmap: (1) audit your current packaging portfolio by material type — plastic 8,200t, cardboard 6,100t, glass 2,800t, metal 1,300t — and map each against PPWR recyclability criteria and recycled content requirements, (2) identify the ten highest-weight packaging formats that fail PPWR requirements and propose redesign options including material substitution, size optimisation, and format elimination, (3) model the financial impact of achieving 30% recycled plastic content across your portfolio including the recycled content premium and Extended Producer Responsibility fee changes under the German dual system, and (4) build a 2025–2030 roadmap with annual milestones for recycled content, recyclability rate, and total packaging weight reduction. Format as a roadmap document with a packaging audit table and a financial impact model.","tags":["packaging","PPWR","circular-economy","Germany","recycled-content"],"author":"AINOW","created":"2024-02-15T11:55:00Z","featured":false},

  {"id":"sus-25","title":"Industrial Symbiosis Network for an Industrial Estate","prompt":"You are the Site Director of a 240-hectare industrial estate in the West Midlands UK housing 38 manufacturing companies across chemicals, food processing, plastics, and logistics. The estate currently sends 12,400 tonnes of material to landfill annually and purchases 890 GWh of energy, much of which could be exchanged between tenants. Design an industrial symbiosis network: (1) map the waste outputs and resource inputs of your 10 largest tenants and identify at least five viable material exchange or energy sharing opportunities — for example, waste heat from a food processor to a greenhouse, CO2 from a fermentation plant to a plastics manufacturer, and spent cooking oil from a food company to a biodiesel producer, (2) quantify the environmental benefit of each exchange in tonnes of waste diverted, tCO2e avoided, and MWh of energy saved, (3) design the legal and contractual framework for a symbiosis exchange including liability, quality specifications, and pricing mechanisms, and (4) calculate the collective benefit: cost savings per company, total landfill cost avoided, and reduction in estate-wide Scope 1 and 2 emissions. Output as a symbiosis network opportunity register, a governance framework outline, and an environmental benefit summary.","tags":["industrial-symbiosis","circular-economy","industrial-estate","waste-exchange","UK"],"author":"AINOW","created":"2024-02-15T12:00:00Z","featured":false},

  {"id":"sus-26","title":"EU Ecodesign for Sustainable Products Compliance Plan","prompt":"You are the Product Development Director at a €380M Finnish electronics company manufacturing wireless headphones, portable speakers, and earbuds sold across the EU. The EU Ecodesign for Sustainable Products Regulation will introduce mandatory requirements including repairability scores, 7-year spare parts availability, minimum recycled content in plastics, and Digital Product Passports. Prepare your product portfolio for compliance: (1) assess your three best-selling product lines against anticipated ESPR technical requirements — repairability score targeting ≥6/10, battery replacement time ≤10 minutes without specialist tools, recycled plastic content ≥25%, and critical raw material circularity, (2) identify the design changes needed for each product including bill of materials changes and structural modifications, (3) specify the data requirements for a Digital Product Passport for your flagship headphone model including all data fields required under the ESPR delegated act for electronics, and (4) estimate the unit cost impact of required design changes and the timeline for integration into your next product generation. Output as a compliance gap analysis table and a product design brief.","tags":["ESPR","Ecodesign","circular-economy","electronics","Digital-Product-Passport"],"author":"AINOW","created":"2024-02-15T12:05:00Z","featured":false},

  {"id":"sus-27","title":"Retailer Food Waste Reduction Programme","prompt":"You are the Operations Sustainability Lead at a UK grocery retailer with 520 stores, £8.4B in annual food sales, and an estimated 98,000 tonnes of food waste per year across stores, distribution centres, and supply chain, equivalent to 156,000 tCO2e using WRAP emission factors. Your commitment under the UK Food Waste Reduction Roadmap is to halve food waste by 2030 from a 2018 baseline. Design the programme: (1) segment food waste by stage of the value chain — supplier 25,000t, distribution 8,000t, stores 52,000t, and consumer-induced 13,000t — identifying primary causes and intervention points at each stage, (2) design three specific interventions per stage with projected tonnes reduced, implementation cost, and timeline — including dynamic pricing algorithms for near-expiry products, supplier root cause analysis workshops, and redistribution partnerships with Fareshare, (3) build a measurement framework using the WRAP Courtauld Commitment methodology specifying data collection frequency and baseline recalculation protocol, and (4) calculate the financial benefit of achieving the 49,000-tonne reduction target including cost of goods saved, reduced disposal costs, and redistribution revenue. Format as a programme design document with a waste reduction potential table.","tags":["food-waste","WRAP","circular-economy","retail","UK"],"author":"AINOW","created":"2024-02-15T12:10:00Z","featured":false},

  {"id":"sus-28","title":"Industrial Equipment Remanufacturing Business Case","prompt":"You are the VP of Aftermarket Services at a US industrial equipment manufacturer with $3.8B in revenues selling compressors, pumps, and motors to the oil and gas and manufacturing sectors. Currently 85% of end-of-life returned equipment is scrapped and only 15% is remanufactured. Your largest customer has asked you to offer remanufactured units at a 35% discount to new as part of their circular procurement policy. Build the remanufacturing business case: (1) model the unit economics of remanufacturing your best-selling 75kW industrial pump — disassembly labour, component inspection, replacement parts, remanufacturing labour, testing, certification, and target selling price at a 35% discount — and compare the margin to selling new units, (2) estimate the addressable market across your installed base of 42,000 pumps, (3) calculate the circular economy benefit: tonnes of steel and copper saved per 1,000 remanufactured units versus new production and Scope 3 Category 12 emission reduction, and (4) design the core-return logistics and quality grading process including IEC 62660-1 State-of-Health testing criteria. Output as a business case with a unit economics model and a market sizing analysis.","tags":["remanufacturing","circular-economy","industrial","scope-3","business-case"],"author":"AINOW","created":"2024-02-15T12:15:00Z","featured":false},

  {"id":"sus-29","title":"Circulytics-Based Circular Economy KPI Framework","prompt":"You are the Circular Economy Programme Manager at a €2.8B Belgian diversified chemicals group committed to Ellen MacArthur Foundation Butterfly diagram principles, wanting to measure circular economy progress across specialty polymers, industrial coatings, and crop protection chemicals. Design a circular economy KPI framework: (1) define 15 KPIs spanning the three circular economy loops — biological cycle (renewable feedstock percentage, biodegradable product percentage), technical cycle (recycled input content, product recyclability rate, remanufacturing yield), and value retention (product lifetime extension, servitisation revenue percentage, waste-to-resource recovery rate), (2) for each KPI specify the measurement methodology, data source, baseline value, and 2030 target, (3) map each KPI to relevant external frameworks — EU Circular Economy Action Plan indicators, Ellen MacArthur Circulytics assessment dimensions, and GRI 301 Materials and GRI 306 Waste disclosures, and (4) design the governance process for quarterly KPI review including dashboard format and escalation thresholds. Output as a KPI register table and a governance framework description.","tags":["circular-economy","KPIs","Ellen-MacArthur","GRI","chemicals"],"author":"AINOW","created":"2024-02-15T12:20:00Z","featured":false},

  {"id":"sus-30","title":"EV Battery Second Life Programme Under EU Battery Regulation","prompt":"You are the Head of Circular Economy at a European electric vehicle manufacturer producing 180,000 vehicles per year, with first-generation 2018–2020 vehicles approaching end-of-battery-first-life at approximately 70–80% remaining State of Health. EU Battery Regulation 2023/1542 requires battery second-life pathways and a battery passport by 2026. Design a second-life battery programme: (1) forecast the volume of end-of-first-life batteries reaching your take-back programme by year from 2025 to 2035 in MWh of total capacity, using your sales data and an average 8-year first-life assumption, (2) assess second-life applications — stationary grid frequency response storage, EV fast-charging buffer storage, and industrial UPS systems — with revenue potential per MWh of repurposed capacity, (3) design the battery grading and sorting process including IEC 62660-1 State-of-Health testing protocol, battery management system data harvesting, and grade-to-application matching, and (4) specify the Digital Battery Passport data fields required under EU Battery Regulation Article 77. Format as a programme design document with a battery volume forecast model and a passport data specification.","tags":["battery","second-life","EU-Battery-Regulation","circular-economy","EV"],"author":"AINOW","created":"2024-02-15T12:25:00Z","featured":false},

  {"id":"sus-31","title":"CS3D-Aligned Supplier Audit Programme","prompt":"You are the Head of Responsible Sourcing at a €1.6B French cosmetics company with 840 Tier 1 suppliers across 52 countries sourcing ingredients including palm oil derivatives, mica, rosewood extract, and synthetic fragrances. You are subject to the French Loi de Vigilance and the incoming EU Corporate Sustainability Due Diligence Directive. Design the supplier audit programme: (1) segment your 840 suppliers into risk tiers using country-level human rights and environmental risk scores from BHRRC data, commodity-level risk using RSPO and RMI databases, and spend level — identify the approximate number of suppliers in each tier, (2) design a tiered audit protocol: Tier 1 high-risk suppliers receive on-site third-party audits against amfori BSCI; Tier 2 medium-risk complete a self-assessment questionnaire; Tier 3 low-risk complete annual declarations, (3) specify the audit scope for a Tier 1 full audit — environmental management, labour rights, health and safety, and business ethics — with at least 30 specific audit checkpoints, and (4) design the corrective action and supplier development process for suppliers with critical non-conformances. Output as an audit programme framework with a supplier segmentation model and a corrective action protocol. [Paste your carbon footprint data or emissions inventory]","tags":["supply-chain","supplier-audit","CS3D","Loi-de-Vigilance","responsible-sourcing"],"author":"AINOW","created":"2024-02-15T12:30:00Z","featured":false},

  {"id":"sus-32","title":"RSPO Certified Palm Oil 100% Transition Plan","prompt":"You are the Sustainable Commodities Manager at a €2.3B German food manufacturer using 42,000 tonnes of palm oil derivatives annually across margarine, bakery, and confectionery lines. Currently 71% of your palm oil is certified RSPO Segregated or Mass Balance, but your largest retail customer requires 100% certified deforestation-free by 2025. Design the transition: (1) map your current palm oil supply chain to mill level using the RSPO supply chain traceability tool, identifying the 15% of volume sourced from mills with known deforestation risk, (2) evaluate certification pathway options — RSPO Mass Balance, Segregated, Identity Preserved, and Book and Claim — and recommend the most commercially viable route to 100% for each supply chain segment, (3) calculate the premium cost of moving from 71% to 100% certified using current RSPO GreenPalm credit prices and Mass Balance premiums, and (4) design a supplier engagement programme with deforestation-risk mills including a 12-month corrective action timeline and escalation triggers. Format as a transition plan with a supply chain risk map, cost model, and supplier engagement framework.","tags":["palm-oil","RSPO","deforestation","supply-chain","sustainable-sourcing"],"author":"AINOW","created":"2024-02-15T12:35:00Z","featured":false},

  {"id":"sus-33","title":"Upstream Transport Scope 3 Decarbonisation Plan","prompt":"You are the Logistics Sustainability Manager at a Swedish home furnishings retailer with €11B in global product sales and 1,800 suppliers primarily in Asia and Eastern Europe. Your Scope 3 Category 4 (upstream transportation) emissions are 890,000 tCO2e per year, of which 68% comes from ocean freight and 22% from air freight. Your SBTi near-term target requires a 30% absolute reduction in Category 4 by 2030. Design a transport decarbonisation programme: (1) analyse the air freight component — identify which product categories are air-freighted due to demand forecasting failures or supplier lead time issues, and quantify the tCO2e premium per tonne of product versus ocean freight using the standard emission factors of 0.8 kgCO2e/tonne-km for air versus 0.016 kgCO2e/tonne-km for ocean, (2) design a modal shift programme to reduce air freight by 80% through improved demand planning and supplier lead time reductions, with a monthly KPI dashboard, (3) evaluate sustainable marine fuel options — biofuels, green methanol, green ammonia — for inclusion in your carrier tender requirements, and (4) model the emission reduction pathway to 2030 showing contribution from each intervention. Format as a transport decarbonisation plan with an emissions reduction waterfall chart specification.","tags":["scope-3","transport","logistics","decarbonisation","SBTi"],"author":"AINOW","created":"2024-02-15T12:40:00Z","featured":false},

  {"id":"sus-34","title":"Human Rights Due Diligence and LkSG Compliance","prompt":"You are the Chief Ethics and Compliance Officer at a $4.1B US technology hardware company sourcing cobalt from DRC, tin from Indonesia, tungsten from Rwanda, and tantalum from Central Africa — all OECD-defined conflict minerals under Dodd-Frank Section 1502. You are also subject to the German Supply Chain Due Diligence Act (LkSG) for your European operations and anticipate CS3D obligations by 2027. Design a human rights due diligence programme: (1) map your conflict minerals supply chain to smelter and refinery level using the Responsible Minerals Initiative RMAP audit programme, identifying the percentage of your sourcing volume from conformant smelters, (2) design a human rights risk assessment for your top 50 Tier 1 suppliers using the UN Guiding Principles on Business and Human Rights, covering forced labour, child labour, freedom of association, and health and safety, (3) specify the grievance mechanism design required under LkSG Article 8, including how workers at supplier sites in remote areas can access it confidentially, and (4) draft the annual LkSG declaration structure required for your German subsidiary. Output as a due diligence programme framework with a conflict minerals traceability table and a grievance mechanism design specification.","tags":["human-rights","supply-chain","LkSG","conflict-minerals","CS3D"],"author":"AINOW","created":"2024-02-15T12:45:00Z","featured":false},

  {"id":"sus-35","title":"Supplier Decarbonisation Engagement Programme","prompt":"You are the Supply Chain Decarbonisation Lead at a €4.8B Dutch retail and e-commerce group whose Scope 3 Category 1 emissions account for 1.2 million tCO2e — 74% of your total GHG inventory. Your SBTi near-term target requires supplier emissions engagement covering 67% of your Category 1 spend by 2027. Design the programme: (1) tier your supplier base by spend and current emissions transparency, identifying the 80 suppliers representing 67% of spend who are the primary engagement targets, (2) design a supplier decarbonisation pathway template asking each supplier to measure and disclose Scope 1+2 emissions using the GHG Protocol, set an SBTi-aligned target, implement at least two energy efficiency measures, and report annually via CDP Supply Chain, (3) design a supplier incentive structure — preferential payment terms for sustainability milestones, joint investment in on-site renewable energy, and public recognition in your sustainability report — plus an escalation process for non-engaging suppliers, and (4) model the total emission reduction potential if all 80 suppliers achieve a 30% Scope 1+2 reduction by 2030. Format as a programme design document with a supplier engagement letter template and a progress tracking dashboard specification.","tags":["supply-chain","decarbonisation","scope-3","supplier-engagement","SBTi"],"author":"AINOW","created":"2024-02-15T12:50:00Z","featured":true},

  {"id":"sus-36","title":"Living Wage Implementation Across Garment Supply Chain","prompt":"You are the Responsible Business Director at a UK clothing retailer sourcing 85 million garments per year from 340 factories in Bangladesh, Pakistan, Cambodia, and Ethiopia. Your Board has committed to paying a living wage to all workers in your Tier 1 supply chain by 2026, using the Anker Research Institute methodology. Design the implementation programme: (1) calculate the living wage gap for each sourcing country — the difference between current average factory wages and the Anker benchmark — and estimate the total cost to close the gap expressed as an increase in cost of goods in £/garment and as a percentage of average selling price, (2) design a fair pricing model that embeds living wage costs into your purchasing prices, replacing standard open-cost-minus negotiation with a transparent cost breakdown model, (3) specify the verification process for living wage payment at factory level, including the role of payroll audits and worker voice mechanisms such as the Worker Wellbeing Index, and (4) design the brand communication strategy for the public commitment launch. Format as a programme implementation plan with a living wage gap analysis table and a sourcing price model.","tags":["living-wage","supply-chain","garments","human-rights","responsible-sourcing"],"author":"AINOW","created":"2024-02-15T12:55:00Z","featured":false},

  {"id":"sus-37","title":"EU Deforestation Regulation Compliance System","prompt":"You are the Commodities Sustainability Manager at a Swiss food trading company with $18B in annual revenues trading soy, beef, cocoa, coffee, timber, and rubber — the six highest-deforestation commodities under the EU Deforestation Regulation. EUDR requires due diligence statements with geolocation data for all land parcels where commodities are produced. Design your compliance system: (1) map your current data availability for each commodity against EUDR requirements — do you have plot-level GPS polygon data for each farmer or estate? If not, design the data collection plan, (2) specify the deforestation risk assessment methodology using satellite-based monitoring systems such as Global Forest Watch, Satelligence, or Starling to verify no deforestation has occurred on supply-chain land parcels after 31 December 2020, (3) design the IT system architecture for storing, processing, and submitting due diligence statements to the EU Information System including data security and supplier data sharing agreements, and (4) estimate the compliance programme cost per commodity including supplier data collection, remote sensing monitoring, IT build, and staff capacity. Output as a compliance implementation plan with a commodity readiness assessment table.","tags":["EUDR","deforestation","supply-chain","compliance","agriculture"],"author":"AINOW","created":"2024-02-15T13:00:00Z","featured":false},

  {"id":"sus-38","title":"Battery Minerals Traceability from Mine to Cell","prompt":"You are the Director of Supply Chain Integrity at a €6.2B German automotive OEM using approximately 2,400 tonnes of cobalt, 890 tonnes of lithium, and 340 tonnes of rare earth elements annually in EV battery production. The EU Battery Regulation's due diligence requirements and your corporate human rights policy require a battery mineral traceability system from mine to cell. Design the system: (1) map the full supply chain tiers for cobalt — from artisanal and large-scale mines in DRC through cobalt hydroxide processors, cobalt sulphate refiners, cathode active material producers, cell manufacturers, to your battery pack assembly — identifying traceability gap points where chain-of-custody breaks, (2) evaluate three traceability technology options: blockchain-based provenance tracking via Minespider, isotope fingerprinting for mineral origin verification, and mass balance chain-of-custody under the IRMA standard, assessing each against EU Battery Regulation requirements and implementation cost, (3) specify the data fields required in a Digital Battery Passport for cobalt under EU Battery Regulation Annex XIII, and (4) design the governance structure for managing traceability data across your 12 cell supplier relationships. Output as a traceability system design document with a technology evaluation matrix.","tags":["minerals","traceability","EU-Battery-Regulation","cobalt","supply-chain"],"author":"AINOW","created":"2024-02-15T13:05:00Z","featured":false},

  {"id":"sus-39","title":"Nordic Public Sector Sustainable Procurement Policy","prompt":"You are the CPO of a Nordic public sector organisation with an annual procurement budget of NOK 4.2B across IT hardware, facilities management, professional services, and catering. The Norwegian Public Procurement Act requires environmental criteria in all public tenders and your municipality has a 2030 carbon-neutral operations target. Design a sustainable procurement policy framework: (1) develop environmental weighting criteria for tender evaluation across your four main categories — specify the environmental criteria, minimum threshold requirements, and percentage weighting achieving at least 30% for environmental criteria under Norwegian procurement guidance, (2) define preferred ecolabel and certification requirements by category: Nordic Swan Ecolabel and EU Ecolabel for products, ISO 14001 or EMAS for service providers, EPDs for construction materials, and TCO Certified for IT equipment, (3) design a supplier sustainability pre-qualification questionnaire with 15 questions covering GHG emissions management, circular economy practices, and supply chain labour standards, and (4) build a contract management process to verify environmental commitments made at tender stage are delivered during contract execution. Format as a procurement policy document with category-specific requirements tables.","tags":["sustainable-procurement","public-sector","Nordic","ecolabels","policy"],"author":"AINOW","created":"2024-02-15T13:10:00Z","featured":false},

  {"id":"sus-40","title":"Scope 3 Category 1 Hotspot Analysis and Substitution Roadmap","prompt":"You are the Carbon Analyst at a €1.1B Swiss personal care company with 320 raw material inputs and a Scope 3 Category 1 inventory of 285,000 tCO2e calculated using Ecoinvent 3.9 spend-based factors. Conduct a hotspot analysis to prioritise decarbonisation investment: (1) rank your top 20 raw materials by spend-weighted emission intensity, identifying the five ingredients — likely petroleum-derived surfactants, synthetic fragrances, and aluminium packaging — that together account for more than 60% of Category 1 emissions, (2) for each of the top five hotspot ingredients, identify available low-carbon substitutes such as bio-based surfactants from sugar cane, natural fragrance alternatives, and recycled aluminium, and estimate the emission reduction per tonne of ingredient substituted, (3) calculate the cost premium for each substitution and the break-even point assuming carbon pricing at €75/tCO2e, and (4) build a three-year substitution roadmap prioritising substitutions by emission reduction per euro of additional cost. Format as a hotspot analysis report with a ranked ingredient table, substitution options register, and roadmap timeline. [Paste your carbon footprint data or emissions inventory]","tags":["scope-3","hotspot-analysis","supply-chain","raw-materials","decarbonisation"],"author":"AINOW","created":"2024-02-15T13:15:00Z","featured":false},

  {"id":"sus-41","title":"Infrastructure Group Sustainability Materiality Assessment","prompt":"You are the Head of Strategy and Sustainability at a €3.7B Spanish infrastructure and construction group with operations in Europe, Latin America, and the Middle East employing 28,000 people. Your Board has approved a new 5-year sustainability strategy and you need to conduct a comprehensive materiality assessment. Design the process: (1) compile a long list of potential material topics using peer benchmark analysis of the top 10 listed infrastructure companies, SASB Engineering and Construction Services standards, GRI 3 Topic List, and ESRS topic list — resulting in approximately 35 candidate topics, (2) design the stakeholder engagement process: an online survey to 2,400 employees and 180 suppliers, structured interviews with 12 institutional investors, and a workshop with your top 25 customers including three government transport ministries, (3) score each topic on two axes — stakeholder importance scored 1–5 from engagement outputs and business financial materiality scored 1–5 by your CFO and risk team — and produce a materiality matrix, and (4) recommend the top 12 material topics and map them to your five strategic pillars. Output as a materiality assessment methodology document with a topic scoring template and a materiality matrix description. [Describe your organization and current sustainability situation]","tags":["materiality","strategy","ESRS","stakeholder-engagement","infrastructure"],"author":"AINOW","created":"2024-02-15T13:20:00Z","featured":false},

  {"id":"sus-42","title":"Sustainability Governance and Board Oversight Design","prompt":"You are the incoming Chief Sustainability Officer at a FTSE 100 UK consumer goods company with £6.2B in revenues and a new Board-level mandate to embed sustainability into governance. Currently sustainability is managed by a two-person team within Corporate Affairs with no direct Board oversight and no sustainability-linked executive remuneration. Design the new governance structure: (1) define the Board sustainability committee terms of reference — composition including minimum two independent NEDs with sustainability expertise, meeting frequency, key responsibilities including strategy approval and climate risk oversight, and reporting line to the full Board, (2) design the executive sustainability steering committee structure with C-suite membership and integration with the existing risk committee and investment committee, (3) specify the first-year remuneration linkage proposal connecting 15% of annual bonus for the CEO, CFO, and five business unit managing directors to three sustainability KPIs — Scope 1+2 emissions reduction, employee safety TRIFR, and women in senior leadership percentage — with proposed baseline and target levels, and (4) design the sustainability reporting cadence from site level to Board level including data governance and sign-off responsibilities. Format as a governance design document with committee terms of reference and a remuneration linkage proposal. [Describe your organization and current sustainability situation]","tags":["governance","sustainability-strategy","executive-remuneration","Board","CSO"],"author":"AINOW","created":"2024-02-15T13:25:00Z","featured":false},

  {"id":"sus-43","title":"20-KPI Sustainability Framework for a Listed Packaging Company","prompt":"You are the Sustainability Director at a €2.2B Austrian packaging company with 9,400 employees listed on the Vienna Stock Exchange. An incoming ESG fund investor has asked for a comprehensive sustainability KPI framework with externally verified targets before increasing their stake. Design the framework: (1) define 20 sustainability KPIs across five pillars — Climate (4 KPIs including Scope 1/2/3 absolute reduction and renewable energy percentage), Circular Economy (4 KPIs including recycled content and recyclability rate), People (4 KPIs including TRIFR, gender pay gap, and training hours), Supply Chain (4 KPIs including suppliers with ESG assessment and living wage verified suppliers), and Governance (4 KPIs including Board diversity, anti-corruption training completion, and sustainability-linked debt percentage), (2) for each KPI specify the 2023 baseline value, 2025 interim target, and 2030 long-term target with calculation methodology, (3) identify which KPIs require external assurance and at what level — limited versus reasonable assurance, and (4) map each KPI to the relevant reporting framework: CSRD/ESRS, GRI, CDP, and TCFD. Format as a KPI register with targets table and an assurance scope recommendation.","tags":["KPIs","targets","sustainability-strategy","ESG","packaging"],"author":"AINOW","created":"2024-02-15T13:30:00Z","featured":false},

  {"id":"sus-44","title":"TNFD Nature Positive Strategy for a Forestry Company","prompt":"You are the Chief Sustainability Officer at a €1.9B Finnish forestry and paper company operating 640,000 hectares of FSC-certified forest and four pulp and paper mills. Your largest customers in Germany and France have asked you to align with the Kunming-Montreal Global Biodiversity Framework target of halting and reversing nature loss by 2030. Design a nature positive strategy: (1) conduct a nature dependency and impact assessment using the TNFD LEAP approach — Locate, Evaluate, Assess, Prepare — identifying your top five dependencies on ecosystem services (timber, water regulation, carbon sequestration, soil health, pollination) and top five impacts on biodiversity (habitat conversion, water extraction, chemical inputs, noise, invasive species), (2) set nature positive targets aligned with the Science Based Targets for Nature framework, specifying a measurable biodiversity metric such as Mean Species Abundance and a 2030 target, (3) design three flagship nature restoration programmes across your forest estate with estimated hectares restored, species supported, and biodiversity metric improvement, and (4) define your TNFD-aligned disclosure structure for your annual report. Format as a strategy document with a TNFD LEAP assessment summary and a biodiversity target statement.","tags":["TNFD","biodiversity","nature-positive","FLAG","forestry"],"author":"AINOW","created":"2024-02-15T13:35:00Z","featured":false},

  {"id":"sus-45","title":"€45M Sustainability Investment Programme CFO Business Case","prompt":"You are the CSO of a €1.3B Dutch food ingredients company preparing a Board paper to justify a €45M sustainability investment programme over three years: €12M energy efficiency, €18M renewable energy, €8M supply chain decarbonisation, and €7M reporting and assurance infrastructure. Your CFO is sceptical and wants a rigorous financial business case. Build the case: (1) for the €12M energy efficiency investment, calculate the payback period and IRR using Dutch industrial electricity at €0.18/kWh and projected annual savings of 28 million kWh, (2) for the €18M renewable energy investment, model the NPV of a 15-year corporate PPA at €85/MWh versus grid electricity at €0.18/kWh for 95 GWh of annual consumption, (3) quantify the revenue risk avoided: model the revenue at risk from EU Taxonomy sustainable finance requirements given your €380M of bank debt maturing by 2027 with lenders applying sustainability-linked pricing, (4) model the avoided EU ETS cost using a carbon price trajectory from €65/tCO2e today to €150/tCO2e by 2030 for your 42,000 tCO2e Scope 1 position, and (5) estimate the MSCI ESG rating upgrade impact on cost of capital. Output as a CFO-ready Board paper with an investment prioritisation table and a 10-year financial impact model.","tags":["business-case","CFO","sustainability-finance","ROI","strategy"],"author":"AINOW","created":"2024-02-15T13:40:00Z","featured":false},

  {"id":"sus-46","title":"Net Zero Roadmap for a 14-Site Manufacturing Group","prompt":"You are the Net Zero Programme Director at a €2.6B German automotive components manufacturer with 14 production sites, 22,000 employees, and a 2022 GHG inventory of Scope 1: 89,000 tCO2e, Scope 2 location-based: 142,000 tCO2e, and Scope 3: 1.8 million tCO2e. Your SBTi near-term targets are Scope 1+2 -46% by 2030 and Scope 3 -30% by 2030, with a long-term net zero target of 2040. Build the net zero roadmap: (1) design the Scope 1+2 reduction pathway to 2030 as a waterfall chart showing contributions from five levers — energy efficiency saving 18,000 tCO2e, fuel switching to green hydrogen at two high-temperature sites saving 22,000 tCO2e, on-site solar PV at all 14 sites saving 14,000 tCO2e, corporate PPA eliminating 88,000 tCO2e of Scope 2, and heat pump electrification saving 15,000 tCO2e, (2) design the Scope 3 supply chain engagement programme targeting the 30% reduction, (3) identify technology gaps — specifically green hydrogen availability and cost — and contingency measures if these are unresolved by 2030, and (4) build the programme governance structure with annual milestones, budget allocation by lever, and Board reporting cadence. Format as a net zero roadmap document with a waterfall chart specification and an investment budget table.","tags":["net-zero","roadmap","manufacturing","SBTi","Germany"],"author":"AINOW","created":"2024-02-15T13:45:00Z","featured":false},

  {"id":"sus-47","title":"Family-Owned Business First Sustainability Strategy","prompt":"You are a sustainability consultant engaged by a third-generation family-owned Italian ceramic tile manufacturer with €280M in revenues, 1,400 employees, and no formal sustainability programme. The owning family wants to invest €2M per year over 5 years. The company has significant environmental impact: 12,400 tCO2e Scope 1 emissions from gas-fired kilns, 280 million litres of water consumed annually, and 8,400 tonnes of production waste. Design a pragmatic 5-year sustainability strategy: (1) assess which frameworks are appropriate for this size and ownership structure — is CSRD applicable? Should they pursue B-Corp certification? What is the value of GRI Essentials reporting? — and recommend a right-sized approach, (2) design a 5-year decarbonisation roadmap for the kilns covering efficiency improvement via infrared sensors and heat recovery, electrification feasibility, and green gas options, with estimated tCO2e reductions and capital costs, (3) identify three quick-win initiatives achievable in year one with a combined budget under €200K that will demonstrate Board commitment internally and externally, and (4) design the internal sustainability governance for a family-owned business without a dedicated sustainability team. Format as a strategic plan with an investment roadmap and a governance structure.","tags":["SME","family-business","sustainability-strategy","B-Corp","Italy"],"author":"AINOW","created":"2024-02-15T13:50:00Z","featured":false},

  {"id":"sus-48","title":"ESG Due Diligence Framework for M&A","prompt":"You are the Group Sustainability Director at a €8.4B European industrial conglomerate conducting due diligence on a potential €650M acquisition of a Spanish specialty chemicals manufacturer. Your investment committee has asked for a sustainability due diligence report alongside standard financial and legal review, after ESG risks in two previous acquisitions led to material impairments. Design the framework: (1) define the scope and structure of the sustainability due diligence covering: climate risk and GHG liability including EU ETS exposure and stranded asset risk, environmental compliance and contaminated land liability, supply chain human rights risks, ESG regulatory compliance gaps including CSRD readiness and CS3D obligations, and reputational ESG risks, (2) design a 20-question ESG data request to the target company specifying documents and data required to assess each risk area, (3) build an ESG risk rating system scoring the target from 1 (low risk) to 5 (deal-breaking risk) per area producing an overall ESG risk score, and (4) identify the three most likely ESG issues in a Spanish specialty chemicals acquisition and draft corresponding conditions precedent or price adjustment mechanisms. Format as a due diligence framework document with a data request template and an ESG risk rating matrix.","tags":["M&A","due-diligence","ESG","acquisition","chemicals"],"author":"AINOW","created":"2024-02-15T13:55:00Z","featured":false},

  {"id":"sus-49","title":"Sustainability-Linked Debt Portfolio Transition Strategy","prompt":"You are the Group Treasurer at a €3.1B Danish wind energy services company with €1.4B of existing bank debt and €400M in bonds maturing over the next four years. Your Board wants to transition the entire debt portfolio to sustainability-linked instruments by 2026. Design the strategy: (1) select five KPIs suitable for sustainability-linked loan and sustainability-linked bond structures using LSTA/LMA Sustainability-Linked Loan Principles and ICMA SLB Principles — KPIs must be material to your business, ambitious, measurable, and externally verified, (2) define the step-up and step-down coupon mechanisms specifying the interest rate margin adjustment if KPI targets are met or missed, typically ±15–25 basis points, (3) assess whether your operations qualify for green bond issuance under the EU Green Bond Standard for eligible green expenditure categories — specify which capex items would qualify, and (4) build the second-party opinion brief for a sustainability rating agency such as Sustainalytics or ISS-ESG covering your sustainability strategy alignment, KPI ambition assessment, and framework governance. Format as a treasury strategy document with a KPI selection table and a debt instrument roadmap.","tags":["sustainability-linked-finance","green-bonds","treasury","SLL","SLB"],"author":"AINOW","created":"2024-02-15T14:00:00Z","featured":false},

  {"id":"sus-50","title":"Employee Sustainability Engagement and Green Ambassador Programme","prompt":"You are the Head of People and Culture at a 6,800-employee UK financial services group with an ambitious net zero commitment but low employee awareness: only 34% of employees understand the company's sustainability strategy per your last all-employee survey. Design a comprehensive engagement programme: (1) design a three-tier green ambassador network — a paid Sustainability Champion in each of your 12 offices with 20% dedicated time, a volunteer Green Team of 3–5 members per floor, and a company-wide sustainability community of practice with monthly webinars — with role descriptions, training curriculum, and performance objectives, (2) design a gamified employee sustainability challenge using a digital platform such as Earthly or Giki Zero for Teams, with team-based competitions across six categories — travel, energy, food, purchasing, community, and advocacy — and monthly prizes and an annual sustainability awards ceremony, (3) develop a sustainability literacy programme integrated into onboarding and mandatory annual training covering net zero concepts, your company's commitments, the role of financial services in the transition, and individual actions, and (4) define the measurement framework specifying which employee engagement metrics you will track quarterly and your 2026 target engagement score. Format as a programme design document with role descriptions, training outline, and a KPI framework.","tags":["employee-engagement","culture","net-zero","green-team","financial-services"],"author":"AINOW","created":"2024-02-15T14:05:00Z","featured":false},

  {"id":"sus-51","title":"Corporate PPA Structuring and Counterparty Assessment","prompt":"You are the Head of Energy Procurement at a €4.2B Swedish manufacturing group consuming 680 GWh of electricity annually across 22 production sites in Sweden, Poland, and Spain. Your Board has approved a target of 100% renewable electricity by 2026 under RE100, and your current Guarantees of Origin cover only 41% of your consumption. You need to structure a portfolio of Corporate Power Purchase Agreements to close the gap. Design the PPA strategy: (1) analyse your consumption profile by country and site against the available renewable energy developer pipeline — Nordic offshore wind, Polish onshore wind, and Spanish solar — and recommend a multi-country PPA portfolio mix that minimises basis risk and profile risk, (2) evaluate the three main PPA contract structures — physical sleeved PPA, financial contract for difference, and virtual PPA — for each country, specifying the accounting treatment under IFRS 9 and the impact on your market-based Scope 2 emissions, (3) conduct a counterparty credit assessment framework for renewable energy developers, specifying the minimum credit rating, parent company guarantee requirements, and performance liquidated damages provisions, and (4) model the 15-year financial impact of a 350 GWh/year PPA at a fixed price of €68/MWh versus your current average grid price of €0.14/kWh with a 4% annual escalation. Output as a PPA strategy document with a portfolio mix recommendation and a financial comparison model.","tags":["PPA","renewable-energy","RE100","scope-2","energy-procurement"],"author":"AINOW","created":"2024-02-15T14:10:00Z","featured":false},

  {"id":"sus-52","title":"ISO 50001 Energy Management System Implementation","prompt":"You are the Energy Manager at a 1,200-employee UK food manufacturing company with three production sites consuming a combined 48 GWh of electricity and 92 GWh of natural gas annually, with an annual energy bill of £9.4M. Your parent company has mandated ISO 50001 certification at all sites by the end of next year to qualify for the Enhanced Capital Allowance scheme and demonstrate commitment to your SBTi Scope 1+2 target of -42% by 2030. Design the ISO 50001 implementation programme: (1) map the ISO 50001 Plan-Do-Check-Act cycle against your three sites, identifying the significant energy uses — compressed air, refrigeration, steam generation, and HVAC — that together account for more than 80% of consumption, (2) design the energy baseline and EnPI (Energy Performance Indicator) framework, specifying which production variables to normalise against for each significant energy use, (3) develop the energy opportunity register for each site using the ISO 50001 energy review process, quantifying the top ten opportunities in MWh and £ per year, and (4) build the certification project plan including gap assessment, implementation tasks, internal audit schedule, and certification audit timeline for all three sites. Output as an implementation programme plan with an energy opportunity register template and a project Gantt chart.","tags":["ISO-50001","energy-management","energy-efficiency","manufacturing","UK"],"author":"AINOW","created":"2024-02-15T14:15:00Z","featured":false},

  {"id":"sus-53","title":"On-Site Solar PV and Battery Storage Feasibility Study","prompt":"You are the Sustainability and Facilities Director at a US distribution company operating eight warehouse facilities with a combined roof area of 420,000 sq ft across Texas, Ohio, and California. Your annual electricity consumption is 28 GWh with peak demand charges representing 31% of your total electricity bill. You want to assess the feasibility of on-site solar PV combined with battery energy storage systems at your top four sites. Conduct the feasibility study: (1) estimate the nameplate solar PV capacity achievable at each of the four sites based on roof area, orientation, and shading, and calculate the annual generation in MWh using NREL PVWatts data for each location, (2) design the battery storage system sizing at each site to target a 40% reduction in monthly peak demand charges, specifying the battery chemistry, usable energy capacity in kWh, and discharge duration, (3) model the financial case for each site: capital cost per kWp, ITC tax credit under the Inflation Reduction Act, payback period, and 25-year NPV assuming electricity price escalation of 3% per year, and (4) calculate the Scope 2 emission reduction in tCO2e per year using eGRID subregion emission factors. Format as a four-site feasibility comparison table with detailed financial models for the top two sites.","tags":["solar-PV","battery-storage","on-site-generation","Scope-2","IRA"],"author":"AINOW","created":"2024-02-15T14:20:00Z","featured":false},

  {"id":"sus-54","title":"Green Hydrogen Feasibility for Industrial Decarbonisation","prompt":"You are the Decarbonisation Director at a €1.7B Belgian steel service centre using 180 GWh of natural gas annually in annealing and heat treatment furnaces, generating 34,000 tCO2e of Scope 1 emissions. You are evaluating green hydrogen as a fuel switching option to achieve your 2032 Scope 1 net zero target for process heat. Conduct a green hydrogen feasibility assessment: (1) calculate the hydrogen demand to replace your natural gas consumption, accounting for the difference in volumetric energy content (natural gas ~10.5 kWh/m3, hydrogen ~3.0 kWh/m3) and the burner efficiency differences requiring furnace modification, (2) evaluate the three supply scenarios — onsite electrolysis connected to a dedicated wind PPA, pipeline delivery from a hydrogen backbone network, and compressed tube trailer delivery — comparing the levelised cost of hydrogen (€/kgH2) for each under current and 2030 projected electrolyser cost curves, (3) assess the required furnace modifications and capital cost for hydrogen-ready burner technology, and (4) model the total cost of decarbonisation compared to the EU ETS carbon price trajectory to 2032, identifying the crossover point where green hydrogen becomes cost-competitive with EU ETS allowances. Output as a feasibility report with a supply scenario comparison table and a decarbonisation cost curve.","tags":["green-hydrogen","industrial-decarbonisation","scope-1","fuel-switching","steel"],"author":"AINOW","created":"2024-02-15T14:25:00Z","featured":false},

  {"id":"sus-55","title":"Data Centre Energy and PUE Optimisation Programme","prompt":"You are the Head of IT Sustainability at a global financial services firm operating three owned data centres in London, Frankfurt, and Singapore with a combined IT load of 18 MW and a current average Power Usage Effectiveness of 1.68. Electricity consumption across the three sites totals 105 GWh per year at a blended cost of $0.12/kWh, and your CDP disclosure requires Scope 2 emissions reduction aligned with your 2030 target. Design an energy optimisation programme: (1) identify the top five energy reduction opportunities using ASHRAE data centre energy efficiency standards — hot aisle/cold aisle containment, free cooling economisers, server virtualisation and consolidation, UPS efficiency upgrade, and lighting controls — estimating the PUE improvement and annual MWh saving for each, (2) design a target PUE of 1.35 for all three sites by 2027, specifying the capital investment required per site and the payback period, (3) evaluate renewable energy procurement options for each location: Singapore green tariff, Frankfurt corporate PPA for German onshore wind, and London REGO-backed supply contract, assessing the market-based Scope 2 emission reduction achievable, and (4) assess whether your data centres qualify for the EU Energy Efficiency Directive Article 12 reporting threshold and what disclosures are required. Format as an optimisation programme plan with a site-by-site energy reduction model.","tags":["data-centre","PUE","energy-efficiency","scope-2","IT"],"author":"AINOW","created":"2024-02-15T14:30:00Z","featured":false},

  {"id":"sus-56","title":"Industrial Heat Electrification Roadmap","prompt":"You are the Process Engineering and Sustainability Lead at a €950M Dutch chemical company with four manufacturing sites consuming 320 GWh of natural gas annually for process heat at temperatures ranging from 80°C to 450°C, generating 64,000 tCO2e of Scope 1 emissions. Your SBTi near-term target is a 46% Scope 1 reduction by 2030. Develop an industrial heat electrification roadmap: (1) segment your heat demand by temperature band — low temperature below 150°C representing 38% of demand, medium temperature 150–400°C representing 45%, and high temperature above 400°C representing 17% — and map the available electrification technologies for each band: industrial heat pumps, electric resistance heating, mechanical vapour recompression, and plasma heating, (2) assess the grid connection upgrade requirements for each site to accommodate increased electrical loads, including lead times and capital cost for DSO network reinforcement in the Netherlands, (3) calculate the Scope 1 emission reduction achievable by 2030 if you electrify all sub-150°C heat demand using industrial heat pumps running on renewable electricity, (4) identify the technical and commercial barriers to electrifying medium and high temperature processes and propose a research and pilot programme. Format as a roadmap document with a temperature-banded heat demand table and an electrification investment plan.","tags":["industrial-heat","electrification","scope-1","heat-pump","chemicals"],"author":"AINOW","created":"2024-02-15T14:35:00Z","featured":false},

  {"id":"sus-57","title":"ESOS Compliance and Energy Audit Programme","prompt":"You are the Energy and Carbon Manager at a UK retail group with 480 stores, 12 distribution centres, and a head office complex consuming a combined 312 GWh of energy annually and subject to the UK Energy Savings Opportunity Scheme Phase 3. Your ESOS compliance deadline is 5 December 2027. Design the ESOS compliance programme: (1) assess your organisation's ESOS qualification and the scope of the audit requirement — total employees, turnover, and balance sheet — and confirm whether any subsidiaries require separate qualification assessment, (2) design the energy audit programme covering your four main energy consumption categories: store lighting and HVAC (180 GWh), distribution centre refrigeration and materials handling (78 GWh), transport fleet (34 GWh), and corporate buildings (20 GWh), specifying the audit methodology, sampling strategy, and level of detail required for ESOS compliance, (3) develop a cost-benefit framework for evaluating the energy saving opportunities identified in audits, prioritising by payback period and tonnes of CO2 avoided, and (4) design the Lead Energy Auditor oversight process and the ESOS notification package for submission to the Environment Agency. Output as a compliance programme plan with an energy audit scope document and an opportunity evaluation template.","tags":["ESOS","energy-audit","UK","compliance","retail"],"author":"AINOW","created":"2024-02-15T14:40:00Z","featured":false},

  {"id":"sus-58","title":"Building Portfolio Net Zero Carbon Pathway","prompt":"You are the Head of Sustainability at a UK property management company managing 2.4 million sq ft of commercial office space across 34 buildings, with a total energy consumption of 48 GWh per year and a CRREM-assessed portfolio-wide carbon intensity of 47 kgCO2e/m2/year against a 2030 Paris-aligned pathway of 18 kgCO2e/m2/year. Your investors have set a net zero carbon by 2040 target for the whole portfolio. Design the decarbonisation pathway: (1) segment your 34 buildings into three tiers based on current EPC rating and CRREM carbon stranding risk: Tier 1 high-risk buildings with EPC D/E and stranding before 2030, Tier 2 medium-risk EPC C buildings stranding before 2035, and Tier 3 EPC A/B buildings already on pathway, (2) design an asset-level decarbonisation plan for a representative Tier 1 office building including heat pump replacement of gas boiler, LED lighting retrofit, building management system upgrade, solar PV installation, and EPC improvement from E to B with estimated capex and carbon reduction in kgCO2e/m2/year, (3) model the whole portfolio carbon intensity trajectory to 2040 under three investment scenarios: minimum compliance, moderate retrofit, and accelerated net zero, and (4) evaluate the impact on asset value and exit yield of stranding risk under MEES regulations. Format as a portfolio decarbonisation strategy with an asset segmentation model and a capital investment plan.","tags":["buildings","net-zero-carbon","CRREM","MEES","real-estate"],"author":"AINOW","created":"2024-02-15T14:45:00Z","featured":false},

  {"id":"sus-59","title":"RE100 Commitment Implementation Roadmap","prompt":"You are the Energy Strategy Director at a €7.3B French luxury goods group with 38 manufacturing sites, 620 retail stores, and 18 office buildings across 45 countries consuming a combined 1.8 TWh of electricity annually. Your CEO has just signed the RE100 commitment pledging 100% renewable electricity by 2030. Design the implementation roadmap: (1) segment your electricity consumption by country and identify the renewable procurement mechanism available in each — corporate PPA availability, green tariff quality, EAC market depth, and grid renewable percentage — for your top 15 countries representing 89% of your total consumption, (2) prioritise the procurement actions for 2025–2027 by identifying the 8–10 countries where quality renewable procurement is most straightforward and the additional 5 countries requiring more complex solutions such as virtual PPAs or bilateral agreements, (3) design the governance and contracting process for a portfolio of 6–8 PPAs across different geographies including the currency risk management approach and the Board delegated authority framework, and (4) build a RE100 progress reporting dashboard covering annual renewable electricity percentage, MWh from each procurement instrument, and Scope 2 market-based emissions reduction versus baseline. Format as a strategic implementation plan with a country-level procurement priority matrix.","tags":["RE100","renewable-energy","PPA","scope-2","luxury-goods"],"author":"AINOW","created":"2024-02-15T14:50:00Z","featured":false},

  {"id":"sus-60","title":"SME Energy Efficiency Investment Prioritisation Tool","prompt":"You are a sustainability consultant working with a 280-employee Irish food processing company with an annual energy bill of €1.8M (electricity €1.1M, gas €0.7M) and a Board commitment to reduce energy costs by 25% and Scope 1+2 emissions by 40% by 2028. The company has completed an initial energy audit identifying 14 potential measures. Develop an investment prioritisation framework: (1) build a priority scoring model that ranks the 14 measures using four criteria — capital cost, simple payback period, annual CO2e reduction in tCO2e, and implementation complexity scored 1–5 — with weighting of 15%, 35%, 35%, and 15% respectively, (2) apply the model to your actual top five measures: variable speed drives on three compressors (€42K capex, 2.1 year payback, 180 tCO2e/year saving), LED lighting throughout the facility (€28K capex, 1.8 year payback, 95 tCO2e/year saving), heat recovery from refrigeration condensers (€85K capex, 3.4 year payback, 320 tCO2e/year saving), boiler controls upgrade (€18K capex, 1.2 year payback, 140 tCO2e/year saving), and rooftop solar PV 120 kWp (€95K capex, 5.1 year payback, 86 tCO2e/year saving), (3) calculate the cumulative capital cost and cumulative tCO2e reduction of implementing measures in priority order, and (4) identify available SEAI grant funding for each measure under the SEAI Large Energy Users Support Scheme. Output as a prioritised investment plan with a ranked measures table and a grant funding summary.","tags":["energy-efficiency","SME","investment","Ireland","carbon-reduction"],"author":"AINOW","created":"2024-02-15T14:55:00Z","featured":false},

  {"id":"sus-61","title":"Alliance for Water Stewardship Certification Roadmap","prompt":"You are the Water Stewardship Manager at a €1.1B Portuguese cork and packaging company operating four manufacturing sites in the Alentejo region of Portugal, an area classified as water-stressed under the WRI Aqueduct water risk atlas. Your sites collectively withdraw 2.8 million m3 of water annually from surface water and groundwater sources, and your largest retail customers in the UK and Germany have asked you to achieve Alliance for Water Stewardship (AWS) Core Level certification at your two largest sites by 2026. Design the AWS certification programme: (1) conduct a water risk assessment for each site using the AWS Standard's watershed context analysis, identifying the specific water risks — seasonal drought, groundwater over-extraction, and downstream ecosystem dependency — that are material to your operations and to local communities, (2) map your current water management practices against the 100 AWS performance indicators, identifying gaps at each maturity level from Foundational through to Gold, (3) design a collective action plan engaging local water users — other industrial users, agricultural irrigators, and municipal water authorities — in a catchment-level water stewardship initiative, and (4) build the AWS certification project plan with internal milestones, third-party auditor selection criteria, and the estimated cost of the certification process. Output as a certification programme plan with an AWS gap analysis table and a collective action proposal.","tags":["water-stewardship","AWS","water-risk","Portugal","certification"],"author":"AINOW","created":"2024-02-15T15:00:00Z","featured":false},

  {"id":"sus-62","title":"TNFD Nature-Related Financial Risk Disclosure","prompt":"You are the Chief Risk Officer at a €5.4B Spanish agri-food group operating across the entire food value chain — seed and fertiliser supply, 120,000 hectares of owned farmland, six food processing plants, and distribution to retail across Southern Europe. The Taskforce on Nature-related Financial Disclosures framework requires you to assess and disclose nature-related risks and opportunities. Conduct the TNFD LEAP assessment: (1) Locate: map your direct operations and value chain against priority biomes using the IBAT biodiversity database, identifying which of your owned farmland parcels and supply shed areas overlap with Key Biodiversity Areas, protected areas, or areas of high ecosystem service value, (2) Evaluate: assess your top five dependencies on ecosystem services — pollination, soil fertility, freshwater regulation, pest control, and climate regulation — and your top five impacts on nature — land conversion, freshwater extraction, nutrient runoff, pesticide use, and greenhouse gas emissions, (3) Assess: identify which nature-related risks (physical, transition, and systemic) are financially material to your P&L and balance sheet, with specific attention to physical crop yield risk from pollinator decline and transition risk from the EU Nature Restoration Law, and (4) Prepare: design the TNFD-aligned disclosure section for your annual report including governance, strategy, risk management, and metrics and targets pillars. Format as a TNFD LEAP assessment document with a nature risk materiality matrix.","tags":["TNFD","nature-risk","biodiversity","agri-food","disclosure"],"author":"AINOW","created":"2024-02-15T15:05:00Z","featured":false},

  {"id":"sus-63","title":"Net Positive Water Strategy for a Beverage Company","prompt":"You are the Global Water Director at a €3.6B Belgian brewing and soft drinks company that uses 4.2 litres of water per litre of beverage produced (industry benchmark: 3.5 L/L) and operates breweries in eight countries including water-stressed regions of Mexico, South Africa, and India. Your CEO has committed to achieving net positive water balance — replenishing more water than you withdraw in water-stressed catchments — by 2030. Design the net positive water strategy: (1) prioritise your brewery sites by water risk using the WRI Aqueduct 3.0 tool, identifying the five sites in high or extremely high baseline water stress where net positive targets are most material, (2) for each priority site, design a water replenishment portfolio using a combination of three intervention types — on-site process efficiency (targeting 3.0 L/L average across priority sites), supply chain agricultural water reduction (working with barley and hop farmers), and catchment restoration projects (wetland restoration, reforestation, and community water infrastructure) — with quantified replenishment volumes in m3/year, (3) establish a science-based water target aligned with the Science Based Targets for Nature freshwater guidance for each priority catchment, specifying the metric, baseline, and target, and (4) design the annual water accounting methodology to verify net positive status. Format as a strategy document with a site priority matrix and a replenishment portfolio table.","tags":["water","net-positive","water-stewardship","brewing","SBT-nature"],"author":"AINOW","created":"2024-02-15T15:10:00Z","featured":false},

  {"id":"sus-64","title":"Corporate Biodiversity Action Plan for an Urban Headquarters","prompt":"You are the Sustainability Manager at a 2,200-employee UK insurance company headquartered in a 6-hectare urban campus in Bristol, with five additional regional offices. Your Board has signed up to the Business for Nature pledge and wants to publish a Biodiversity Action Plan demonstrating your company's commitment to the Kunming-Montreal 30x30 target. Design a Corporate Biodiversity Action Plan: (1) conduct a baseline biodiversity survey framework for your Bristol campus — specifying the survey methods to quantify species richness, habitat quality using the UK Biodiversity Metric 4.0, and ecosystem services provided by your existing green spaces including 1.2 hectares of managed lawns and 0.4 hectares of mature tree canopy, (2) design five specific habitat improvement interventions for the Bristol campus — wildflower meadow establishment, native hedgerow planting, bat and bird nesting installations, green roof retrofit on your 1,200 m2 flat roof extension, and a sustainable drainage pond — with species targets and biodiversity unit gains under the UK Biodiversity Metric, (3) extend the plan to your supply chain and investment portfolio, identifying three nature-positive supplier criteria and two biodiversity screening criteria for your property investment decisions, and (4) define the monitoring and reporting framework including annual species count methodology and disclosure alignment with TNFD. Format as a Biodiversity Action Plan document with a campus habitat improvement schedule.","tags":["biodiversity","BAP","UK-Biodiversity-Metric","urban","TNFD"],"author":"AINOW","created":"2024-02-15T15:15:00Z","featured":false},

  {"id":"sus-65","title":"Nature-Based Solutions Portfolio for Carbon and Biodiversity","prompt":"You are the Head of Climate and Nature at a €2.9B Austrian forest products company owning 280,000 hectares of managed forest in Austria and Romania. You are developing a nature-based solutions portfolio that simultaneously addresses your residual GHG emissions under your net zero plan and your biodiversity commitments under the Kunming-Montreal framework. Design the NbS portfolio: (1) assess the carbon sequestration potential of three NbS interventions across your forest estate — converting 12,000 hectares of Tier 3 low-productivity plantation to mixed native forest (estimated 4.2 tCO2e/ha/year additional sequestration), rewetting 3,400 hectares of drained peatland in Romania (estimated 8.1 tCO2e/ha/year of emission avoidance), and establishing 2,200 km of forested riparian buffer strips (estimated 2.8 tCO2e/ha/year sequestration), (2) quantify the biodiversity co-benefits of each intervention using the IUCN Habitat Classification and Mean Species Abundance as metrics, (3) evaluate whether these interventions can generate REDD+ or VCS-verified carbon credits for sale, including the certification requirements and the revenue potential per tCO2e at current voluntary market prices, and (4) assess the long-term permanence risk of each NbS intervention under RCP 4.5 and 8.5 climate scenarios. Format as an NbS portfolio assessment with a carbon and biodiversity benefit register and a permanence risk analysis.","tags":["nature-based-solutions","carbon-sequestration","biodiversity","forestry","REDD+"],"author":"AINOW","created":"2024-02-15T15:20:00Z","featured":false},

  {"id":"sus-66","title":"Science-Based Targets for Nature Freshwater Assessment","prompt":"You are the Environmental Director at a €1.4B Finnish paper mill company with three mills in Finland and one in Portugal, withdrawing a combined 28 million m3 of freshwater per year from rivers and groundwater, and discharging 24 million m3 of treated effluent. The Science Based Targets Network has published freshwater guidance under Science Based Targets for Nature, and your Board has committed to setting catchment-level science-based freshwater targets. Design the freshwater target-setting process: (1) characterise the water withdrawal and discharge quality for each of your four mills including key pollutants — biochemical oxygen demand, suspended solids, phosphorus, and temperature — and benchmark against IPPC permit requirements and relevant EU Water Framework Directive Environmental Quality Standards, (2) assess the ecological status of the four receiving water bodies using WFD monitoring data, identifying whether your discharges are contributing to failure to achieve Good Ecological Status, (3) apply the SBTfN freshwater methodology to set site-level environmental flow limits for each mill based on the reference ecological flow requirements of each catchment, specifying the seasonal withdrawal limits in m3/day, and (4) design the water quality improvement investment plan to meet the targets including CAPEX for effluent treatment upgrades and operational changes. Format as a freshwater target assessment document with a mill-by-mill compliance gap table.","tags":["freshwater","SBT-nature","Water-Framework-Directive","paper-mill","water-quality"],"author":"AINOW","created":"2024-02-15T15:25:00Z","featured":false},

  {"id":"sus-67","title":"Plastic Pollution and Ocean Impact Reduction Strategy","prompt":"You are the Chief Sustainability Officer at a €800M Greek seafood company sourcing from fisheries and aquaculture across the Mediterranean and Atlantic, using 4,200 tonnes of plastic packaging per year and operating a fishing fleet that loses an estimated 3.8 tonnes of abandoned, lost, or discarded fishing gear annually. Design a plastic pollution reduction strategy: (1) audit your plastic footprint across three dimensions — primary packaging (consumer-facing plastic), secondary and tertiary packaging (distribution plastic), and operational plastic (fishing gear, nets, and ropes) — using the Ellen MacArthur Foundation's plastic footprint methodology, (2) design a product packaging redesign programme targeting 50% reduction in virgin plastic use by 2027, including specific material substitutions for your top five packaging formats — vacuum-sealed trays, flow-wrap film, foam trays, shrink wrap, and rigid tubs — and recyclability improvements under the EU Packaging and Packaging Waste Regulation, (3) develop a fishing gear marking and tracking system to reduce ALDFG in compliance with EU Regulation 1380/2013, including GPS tagging of high-value gear and a gear retrieval reward scheme with local fishing communities, and (4) calculate your total plastic pollution impact reduction in tonnes per year and express it as a percentage of the Mediterranean's estimated annual fishing gear waste load. Format as a strategy document with a plastic footprint audit table and a packaging redesign roadmap.","tags":["plastic","ocean","fishing","packaging","circular-economy"],"author":"AINOW","created":"2024-02-15T15:30:00Z","featured":false},

  {"id":"sus-68","title":"EU Taxonomy Alignment Assessment for a Utilities Company","prompt":"You are the Head of Sustainable Finance at a €8.7B German integrated utilities company with revenue streams across electricity generation (wind, solar, and gas peaker plants), electricity distribution, district heating, and energy retail. The EU Taxonomy Regulation requires you to disclose the percentage of Turnover, Capex, and Opex that is taxonomy-aligned for your CSRD reporting. Conduct the taxonomy alignment assessment: (1) map each of your revenue streams against the EU Taxonomy's six environmental objectives and identify which activities are potentially eligible under the Climate Change Mitigation delegated act — specifically assessing electricity generation from wind and solar against the Taxonomy Technical Screening Criteria and the gas peaker plants against the transitional activity thresholds (below 100 gCO2eq/kWh lifecycle), (2) apply the Do No Significant Harm (DNSH) assessment for each eligible activity across all five remaining environmental objectives, identifying the highest-risk DNSH hurdles for each activity, (3) verify the Minimum Social Safeguards requirement by assessing your compliance with OECD Guidelines for Multinational Enterprises and UN Guiding Principles, and (4) calculate your Taxonomy KPIs — Taxonomy-eligible and Taxonomy-aligned percentages for Turnover, Capex, and Opex — and design the disclosure table format required under the Taxonomy Disclosure Delegated Act. Format as a taxonomy assessment report with a screening criteria compliance table and a KPI disclosure template.","tags":["EU-Taxonomy","sustainable-finance","utilities","CSRD","climate-mitigation"],"author":"AINOW","created":"2024-02-15T15:35:00Z","featured":false},

  {"id":"sus-69","title":"Green Bond Framework and Second Party Opinion Preparation","prompt":"You are the Head of Treasury and Capital Markets at a €4.1B Spanish renewable energy developer planning a €500M green bond issuance to fund offshore wind development in the North Sea and solar PV projects in Iberia. You want to issue under the EU Green Bond Standard to maximise investor demand and pricing advantage. Design the green bond framework: (1) specify the eligible green project categories aligned with the EU Taxonomy Climate Change Mitigation Technical Screening Criteria for offshore wind and utility-scale solar PV, including the environmental sustainability criteria and the DNSH assessment for each project type, (2) design the use of proceeds management process — how the €500M will be allocated to eligible projects, the tracking system to ensure ring-fencing, and the treatment of unallocated proceeds, (3) draft the reporting framework: annual allocation report (project descriptions, amounts allocated, expected GHG emission avoidance in tCO2e/year) and impact report (actual kWh generated, tCO2e avoided using IEA country emission factors), and (4) prepare the second-party opinion brief for submission to Sustainalytics or ISS-ESG, including your green bond framework governance, alignment with ICMA Green Bond Principles, and EU GBS compliance assessment. Format as a green bond framework document ready for external review.","tags":["green-bonds","EU-GBS","renewable-energy","sustainable-finance","treasury"],"author":"AINOW","created":"2024-02-15T15:40:00Z","featured":false},

  {"id":"sus-70","title":"PCAF Standard Implementation for a Commercial Bank","prompt":"You are the Head of Sustainable Finance at a €120B Dutch commercial bank with a corporate loan book of €34B across 18 sectors. The Partnership for Carbon Accounting Financials standard requires you to measure and disclose the financed emissions of your lending portfolio. Implement the PCAF methodology: (1) segment your €34B corporate loan book by PCAF asset class — listed equity and corporate bonds, business loans and unlisted equity, project finance, commercial real estate, mortgages, and motor vehicle loans — and identify the applicable PCAF measurement approach for each segment, (2) calculate the financed emissions for your top five sector exposures by outstanding balance — utilities, real estate, food and agriculture, transportation, and manufacturing — using PCAF's attribution factor approach (outstanding loan amount / enterprise value including cash) and available emissions data sources, prioritising PCAF Data Quality Score 1–2 data where available, (3) identify the data gaps where you must use proxy methods — revenue-based emission factors from Exiobase or sector-average intensity data — and estimate the portfolio-level data quality distribution across PCAF scores 1–5, and (4) design the annual financed emissions reporting process including data collection from corporate clients, third-party data provider integration (Trucost, MSCI), and PCAF-aligned disclosure in your TCFD report. Format as a PCAF implementation plan with a portfolio emissions estimate and a data quality assessment.","tags":["PCAF","financed-emissions","banking","TCFD","sustainable-finance"],"author":"AINOW","created":"2024-02-15T15:45:00Z","featured":false},

  {"id":"sus-71","title":"Impact Investment Measurement Framework","prompt":"You are the Chief Impact Officer at a €1.2B Luxembourg-based impact fund investing in climate tech, sustainable food systems, and financial inclusion in emerging markets. Your investors — development finance institutions and European pension funds — require rigorous impact measurement aligned with the IMP (Impact Management Project) five dimensions of impact and the Operating Principles for Impact Management. Design the impact measurement framework: (1) define the impact thesis and theory of change for each of your three investment themes, specifying the target outcomes, the causal pathway from investment to impact, and the counterfactual, (2) design the KPI set for each theme — for climate tech: tCO2e avoided per €1M invested, megawatts of clean energy installed, and number of end users with clean energy access; for sustainable food: hectares under regenerative agriculture, reduction in agricultural water intensity, and smallholder farmer income uplift — with baseline data sources and measurement frequency, (3) apply the IMP's five dimensions of impact to rate a representative portfolio company using the IRIS+ catalogue of standardised metrics, and (4) design the annual impact report structure aligned with the IFC Operating Principles for Impact Management's disclosure requirements, including the independent verification process. Format as an impact measurement framework document with a KPI register and an impact report template.","tags":["impact-investing","IMP","IRIS+","climate-tech","measurement"],"author":"AINOW","created":"2024-02-15T15:50:00Z","featured":false},

  {"id":"sus-72","title":"Transition Finance Framework for a Carbon-Intensive Borrower","prompt":"You are the Sustainable Finance Structuring Director at a major European investment bank advising a €6.8B Polish coal-dependent energy company seeking €800M in transition finance to fund its coal phase-out and renewable energy build-out by 2035. The company operates three coal power plants representing 2.8 GW of capacity and has committed to closing all coal by 2035, one decade ahead of the Polish national energy plan. Structure the transition finance package: (1) assess whether the company's transition plan meets the credibility criteria of the Climate Bonds Initiative's Transition Finance Framework — Paris-alignment of the trajectory, use of proceeds for transition activities, governance of the transition plan, and disclosure commitments, (2) design a blended finance structure combining a climate-focused commercial tranche (€500M), a European Investment Bank or EBRD concessional tranche (€200M) available for just transition activities including coal worker reskilling, and an EU Just Transition Mechanism grant component (€100M), (3) define the covenants and KPIs tied to each tranche including coal capacity closure milestones, renewable capacity commissioned, and workforce transition metrics with step-up interest rate triggers for non-compliance, and (4) assess the EU Taxonomy alignment of the eligible activities and the DNSH risk for each use of proceeds category. Format as a transition finance term sheet outline and a transition plan credibility assessment.","tags":["transition-finance","coal-phase-out","blended-finance","EU-Taxonomy","Poland"],"author":"AINOW","created":"2024-02-15T15:55:00Z","featured":false},

  {"id":"sus-73","title":"ESG Integration into Listed Equity Portfolio Management","prompt":"You are the Head of ESG Integration at a €28B Norwegian asset management firm managing actively managed listed equity funds across global developed markets. Your investment philosophy requires ESG integration into every stage of the investment process, from idea generation to portfolio construction and active ownership. Design the ESG integration methodology: (1) design the negative screening framework — specifying the revenue threshold exclusions for thermal coal (>5% revenue), controversial weapons (zero tolerance), and tobacco (>2% revenue) — and align it with your Norwegian pension fund client guidelines, (2) design the ESG scoring model for fundamental analysis, specifying how MSCI ESG Ratings, Sustainalytics ESG Risk Ratings, and CDP climate scores are incorporated into the analyst valuation process including a methodology for translating ESG risk into a discount rate adjustment (for example, a Sustainalytics High Risk rating adding 50 basis points to WACC), (3) design the active ownership programme: voting policy aligned with the Norwegian Corporate Governance Board code, priority engagement themes for 2025–2026, and an escalation ladder from direct engagement through co-filing resolutions to divestment, and (4) produce the SFDR Article 8 disclosure template for your flagship European equity fund, specifying the Principal Adverse Impact indicators from Annex I of the SFDR Regulatory Technical Standards that you will monitor. Format as an ESG integration methodology document with a PAI monitoring table and a voting policy summary.","tags":["ESG-integration","asset-management","SFDR","active-ownership","Norway"],"author":"AINOW","created":"2024-02-15T16:00:00Z","featured":false},

  {"id":"sus-74","title":"Carbon Credit Market Investment Due Diligence","prompt":"You are the Head of Carbon Markets at a €3.4B UK energy trading company building a voluntary carbon credit trading and investment desk. You are evaluating three carbon project investments: a 50,000 ha REDD+ avoided deforestation project in the Brazilian Amazon (12 million tCO2e over 30 years, Verra VCS+CCB verified), a cookstove distribution programme in Kenya (2.4 million tCO2e over 10 years, Gold Standard), and a direct air capture facility in Iceland (100,000 tCO2e capacity per year, CarbonVault, engineering-backed, permanent storage). Conduct investment due diligence: (1) assess each project against the Oxford Offsetting Principles hierarchy — permanence, additionality, leakage, co-benefits, and MRV robustness — scoring each criterion 1–5 and identifying the specific risk factors for each project type, (2) model the revenue scenario for each investment: current voluntary carbon market price per tCO2e, projected price in 2027 and 2030 under ICVCM Core Carbon Principle endorsed scenarios, and total revenue over the investment horizon, (3) assess the regulatory risk for each project type under the evolving Article 6 of the Paris Agreement and the Integrity Council for the Voluntary Carbon Market's Core Carbon Principles, and (4) recommend a portfolio allocation across the three project types and design the hedging strategy for carbon price volatility. Format as an investment due diligence report with a project scorecard and a portfolio allocation recommendation.","tags":["carbon-markets","voluntary-carbon","due-diligence","REDD+","investment"],"author":"AINOW","created":"2024-02-15T16:05:00Z","featured":false},

  {"id":"sus-75","title":"SFDR Article 9 Fund Disclosure Package","prompt":"You are the Head of Sustainable Product Development at a €15B French asset management group launching a new €500M SFDR Article 9 fund focused on European biodiversity and ecosystem restoration. Article 9 funds must demonstrate that sustainable investment is their primary objective and disclose this under the SFDR Level 2 Regulatory Technical Standards. Design the full disclosure package: (1) define the fund's sustainable investment objective and the binding sustainability criteria — minimum 80% of holdings must be in companies deriving more than 50% of revenue from biodiversity-positive activities, assessed using the EU Taxonomy Biodiversity and Ecosystem objective Technical Screening Criteria, (2) design the pre-contractual disclosure document (Article 9 SFDR template): investment strategy, how sustainability factors are integrated, the reference benchmark (or explanation of why none is used), the Principal Adverse Impact indicators being monitored, and the due diligence policy for investee companies, (3) specify the ongoing product-level PAI monitoring: the 14 mandatory indicators from Annex I Table 1 plus three opt-in biodiversity-specific indicators (area of protected sites affected, percentage of holdings in TNFD-reporting companies, biodiversity footprint per €1M invested), and (4) design the annual sustainability report structure required under SFDR Article 11, including actual versus targeted sustainable investment percentage and PAI outcomes versus prior year. Format as a complete Article 9 disclosure package outline with a PAI monitoring dashboard template.","tags":["SFDR","Article-9","biodiversity","fund","sustainable-finance"],"author":"AINOW","created":"2024-02-15T16:10:00Z","featured":false},

  {"id":"sus-76","title":"Just Transition Finance for a Coal Region","prompt":"You are the Regional Economic Development Director for the Silesian voivodeship in Poland, home to 85,000 coal mining and coal power workers facing unemployment as Poland accelerates its coal phase-out commitment under EU pressure. You are designing a Just Transition Finance proposal to access the EU Just Transition Fund (JTF) allocation for your region. Design the proposal: (1) assess the socioeconomic impact of coal phase-out on your region: unemployment projections by year from 2025 to 2035 by skill category, affected communities by proximity to coal assets, and the fiscal impact on local government revenues from lost business rates and income tax, (2) design the Just Transition Investment Plan: five flagship investments including a green hydrogen industrial park on the site of a decommissioned coal plant (€120M), a 2,000-person renewable energy technician retraining academy (€45M), regenerative agriculture conversion support for former coal-impacted farmland (€30M), coal mine water treatment and land remediation (€80M), and sustainable tourism infrastructure in the reclaimed landscape (€25M), (3) specify the JTF eligibility criteria compliance for each project and the required co-financing from national and regional budgets, and (4) design the social outcome measurement framework tracking employment creation, worker income replacement, community wellbeing indicators, and environmental remediation progress. Format as a JTF proposal outline with an investment plan table and a social impact measurement framework.","tags":["just-transition","coal","Poland","EU-JTF","regional-development"],"author":"AINOW","created":"2024-02-15T16:15:00Z","featured":false},

  {"id":"sus-77","title":"Sustainability-Linked Loan KPI Design for a Food Company","prompt":"You are the Group CFO of a €1.8B Danish organic food group that has been offered a €300M sustainability-linked revolving credit facility by a consortium of four Nordic banks. The banks have asked you to propose three sustainability KPIs that will drive the margin ratchet mechanism — a 7.5 basis point reduction in margin for each KPI target met, and a 7.5 basis point step-up for each missed. Design the KPI framework: (1) select three KPIs that are material to your business, ambitious relative to your current trajectory, and objectively measurable with external verification — candidates include Scope 1+2 absolute GHG reduction (percentage versus base year), certified organic farmland in your supply chain (percentage of total sourcing by volume), and Science-Based Targets validation (binary milestone), (2) define the baseline and annual target levels for each KPI through 2028, demonstrating that targets represent genuine performance improvement beyond business-as-usual using your historical performance data, (3) specify the independent verification mechanism for each KPI — which data would be assured by your external auditor, which would be verified by a specialist sustainability assurance provider such as Bureau Veritas or SGS, and what reporting calendar applies, and (4) draft the KPI schedule language for inclusion in the SLL term sheet in standard LMA/APLMA format. Format as a KPI schedule document with a target ambition assessment table.","tags":["sustainability-linked-loan","KPIs","food","SLL","Nordic"],"author":"AINOW","created":"2024-02-15T16:20:00Z","featured":false},

  {"id":"sus-78","title":"Annual Sustainability Report Structure and Content Plan","prompt":"You are the Head of Sustainability Communications at a €5.2B Swiss specialty chemical group preparing your 2025 annual sustainability report, which must comply with CSRD, GRI Standards 2021, and TCFD requirements, and target four distinct audiences: institutional ESG investors (primary audience), sustainability-specialist NGOs, business customers with supply chain due diligence needs, and your own 18,000 employees. Design the report structure and content plan: (1) map the three reporting framework requirements — CSRD ESRS disclosures, GRI content index, and TCFD four-pillar structure — onto a single coherent report architecture, specifying which sections serve which framework and which audience, (2) design the opening executive section (CEO and CSO letters, highlights dashboard, and strategic materiality summary) for the institutional investor audience, specifying the three or four headline KPIs and the honest narrative framing that avoids greenwashing, (3) design the digital-first interactive elements for the online version — a dynamic materiality matrix, a Scope 1/2/3 emissions data explorer, and a GRI content index with hyperlinks to source documents, and (4) build the editorial production plan: content owner mapping, drafting schedule, data collection deadlines, legal review, and external assurance timeline. Format as a report design brief with a chapter-by-chapter content specification and a production timeline.","tags":["sustainability-report","CSRD","GRI","TCFD","communications"],"author":"AINOW","created":"2024-02-15T16:25:00Z","featured":false},

  {"id":"sus-79","title":"Investor ESG Roadshow Preparation","prompt":"You are the VP of ESG and Investor Relations at a NASDAQ-listed US semiconductor company with $8.4B in revenues preparing for your annual ESG investor roadshow targeting 25 institutional investors including CalPERS, NBIM, and BlackRock's stewardship team. Your MSCI ESG Rating recently dropped from A to BBB following a governance downgrade. Design the roadshow preparation: (1) analyse the MSCI methodology to identify the specific issues causing the governance downgrade — typically related to board independence, audit committee composition, or executive pay structure — and prepare factual responses to likely investor questions, (2) design the ESG investor presentation deck (15 slides): company overview and ESG materiality, climate strategy and SBTi progress including a 2030 emissions reduction waterfall, supply chain sustainability programme and conflict minerals compliance, board diversity and governance improvements, and a forward-looking ESG commitment timeline, (3) prepare responses to the 10 most likely tough questions from ESG-specialist investors — including your Scope 3 Category 11 emissions from semiconductor power consumption in end products, water use intensity at your Taiwan fabs, and the timeline for board composition improvements, and (4) design the ESG engagement follow-up process: the written commitments to make, the internal owner for each, and the 90-day disclosure update plan. Format as a roadshow preparation pack with a slide outline and a Q&A preparation guide.","tags":["investor-relations","ESG-roadshow","MSCI","governance","semiconductor"],"author":"AINOW","created":"2024-02-15T16:30:00Z","featured":false},

  {"id":"sus-80","title":"NGO and Civil Society Engagement Strategy","prompt":"You are the Head of Stakeholder Engagement at a €4.6B Dutch consumer goods company operating in personal care and household cleaning products, with a supply chain sourcing palm oil, mica, and tropical wood pulp. Three well-resourced NGOs — Global Witness, the Business and Human Rights Resource Centre, and Rainforest Action Network — have each published critical reports on your supply chain in the past 18 months. Design a constructive NGO and civil society engagement strategy: (1) map each NGO's specific concerns against your supply chain geography and commodities, categorising concerns by credibility and alignment with your own due diligence findings — assessing which criticisms are factually accurate, which are based on outdated information, and which are disputed, (2) design differentiated engagement approaches for each NGO: a structured dialogue process for issues where you share a common goal, a formal response and clarification process for factually inaccurate claims, and an escalation protocol if engagement is not productive, (3) develop a proactive transparency initiative — a public supply chain traceability dashboard showing mill-level sourcing data for palm oil and mine-level sourcing data for mica, updated quarterly — that pre-empts future negative reporting, and (4) design an annual multi-stakeholder forum with NGOs, academic experts, and peer companies to develop shared solutions to sector-wide sourcing challenges. Format as an engagement strategy document with a stakeholder map and an NGO response protocol.","tags":["NGO-engagement","stakeholder","supply-chain","transparency","palm-oil"],"author":"AINOW","created":"2024-02-15T16:35:00Z","featured":false},

  {"id":"sus-81","title":"Customer Sustainability Communication Strategy","prompt":"You are the B2B Marketing and Sustainability Director at a €2.1B German industrial gases company supplying hydrogen, oxygen, nitrogen, and specialty gases to 4,200 industrial customers in automotive, food processing, electronics, and healthcare sectors. Your customers are under increasing pressure from their own supply chain decarbonisation obligations and are asking for the carbon footprint of the gases they purchase. Design a customer sustainability communication strategy: (1) build a product-level carbon footprint disclosure programme: calculate the Scope 3 Category 1 emission factor (kgCO2e per Nm3 or per tonne) for each of your top 10 gas products using the GHG Protocol Product Standard, differentiated by production method (steam methane reforming versus electrolysis for hydrogen, air separation for industrial gases) and delivery logistics, (2) design a customer-facing sustainability portal where each customer can access their annual purchased gas carbon footprint, download a Scope 3 Category 1 inventory contribution report for their own GHG accounting, and see the green gas options available to them, (3) design a green product portfolio roadmap: timeline for offering green hydrogen from electrolysis, renewable-powered air separation, and biomethane-based specialty gases, with price premium transparency, and (4) develop a joint sustainability case study template to co-publish with your 20 most sustainability-active customers, demonstrating the Scope 1 reduction their transition to green gas achieves. Format as a customer communication strategy with a product carbon footprint methodology note.","tags":["customer-communication","scope-3","product-carbon-footprint","industrial-gases","B2B"],"author":"AINOW","created":"2024-02-15T16:40:00Z","featured":false},

  {"id":"sus-82","title":"Community Impact and Social Value Reporting","prompt":"You are the Head of Social Sustainability at a UK infrastructure developer constructing a 480 MW offshore wind farm off the Yorkshire coast over a 5-year construction programme with a £2.1B project value. Your Development Consent Order conditions and your ESG reporting commitment require you to measure and report social value creation in the local East Yorkshire community. Design the social value measurement and reporting framework: (1) apply the HM Treasury Green Book social value methodology and the HACT Social Value Bank to quantify the monetary social value of your community investment activities — apprenticeships for local young people, skills training for adults, supplier procurement from local businesses, and community environmental programmes, (2) design a local supply chain monitoring system to track and maximise local procurement spend within a 50-mile radius, including a local supplier development programme to help SMEs meet your qualification standards, (3) measure and report on your workforce inclusion commitments: number of apprenticeships, percentage of workforce from disadvantaged postcodes, gender balance in offshore roles, and pay gap between highest and lowest-paid workers on site, and (4) design the annual social value report aligned with the Social Value UK reporting standards and your project Environmental Statement commitments. Format as a social value framework document with a social value calculation template and a reporting dashboard.","tags":["social-value","community","offshore-wind","UK","infrastructure"],"author":"AINOW","created":"2024-02-15T16:45:00Z","featured":false},

  {"id":"sus-83","title":"Supplier Sustainability Communication and Training Programme","prompt":"You are the Sustainable Supply Chain Communications Manager at a €3.3B Belgian retail group with 1,400 suppliers across Europe and Asia. Your new supplier sustainability code requires all suppliers to achieve a minimum EcoVadis Silver rating by 2026, but only 23% of your supply base has completed an EcoVadis assessment and the average score is 42/100 — below the 45/100 Silver threshold. Design a supplier enablement programme: (1) segment your suppliers by current EcoVadis status and by category — food, non-food, own-label manufacturers, and logistics providers — and design differentiated communication and support pathways for each segment, (2) develop a supplier sustainability capacity building programme: a digital learning academy with 8 self-paced modules covering GHG measurement, waste management, labour standards, and ethical business practices, virtual workshops in four languages (English, French, Chinese, Vietnamese), and one-to-one coaching for your top 50 own-label manufacturers, (3) design the EcoVadis assessment support toolkit: a pre-assessment preparation guide, a document checklist for each EcoVadis theme, a common non-conformance guide with corrective action templates, and a post-assessment improvement planning template, and (4) define the escalation and consequence management process for suppliers who do not achieve Silver by the 2026 deadline. Format as a programme design document with a supplier segmentation model and a learning academy curriculum outline.","tags":["supplier-communication","EcoVadis","capacity-building","supply-chain","Belgium"],"author":"AINOW","created":"2024-02-15T16:50:00Z","featured":false},

  {"id":"sus-84","title":"Internal Sustainability Reporting and Data Quality Management","prompt":"You are the Sustainability Data Manager at a €6.1B Swedish industrial conglomerate with 28 manufacturing sites, 12 countries, and 24,000 employees, preparing your first CSRD sustainability statement which requires assurance from your external auditors. Your current sustainability data collection process relies on quarterly email submissions from site environmental managers into a central Excel workbook, resulting in restatements of historical data in 4 of the last 5 reporting years. Design a fit-for-purpose internal sustainability reporting system: (1) map all ESRS datapoints requiring data collection across your sites, categorising them by collection frequency (monthly, quarterly, annual), data type (quantitative metered, quantitative calculated, qualitative), and data ownership (site, business unit, group function), (2) design the data quality control framework: primary controls at site level (meter reading verification, calculation checks), secondary controls at business unit level (variance analysis, peer benchmarking), and tertiary controls at group level (reasonableness checks, year-on-year trend analysis), (3) specify the technology requirements to replace your Excel process — either a dedicated ESG platform such as Enablon, Intelex, or Sphera, or an extension of your existing SAP environment — with a functional requirements specification for the top 15 most important system capabilities, and (4) design the data governance structure including data stewardship roles, sign-off hierarchy, and the audit trail requirements for ISAE 3000 assurance. Format as a data management design document with a data quality controls matrix and a system requirements specification.","tags":["data-management","CSRD","internal-reporting","data-quality","Sweden"],"author":"AINOW","created":"2024-02-15T16:55:00Z","featured":false},

  {"id":"sus-85","title":"Materiality Communication for Non-Expert Audiences","prompt":"You are the Head of Sustainability Communications at a €1.6B Austrian retail bank with 3,200 employees and 480,000 retail and SME customers. Your Board has approved a comprehensive sustainability strategy addressing climate risk in your lending portfolio, financial inclusion for underserved communities, and responsible investment of your €8.4B asset management arm. You need to communicate this strategy convincingly to three very different audiences. Design the communication plan: (1) for your 480,000 retail customers: design a quarterly sustainability impact statement that shows each customer the carbon footprint of their spending patterns using transaction category emission factors (kgCO2e per €100 of spending by category) and highlights the green financial products available to them — green mortgages, sustainable investment funds, and EV loans, (2) for your 3,200 employees: design an internal sustainability intranet hub with a live emissions dashboard, a personal impact calculator, a green ideas submission portal, and monthly sustainability team update videos featuring real case studies, (3) for your SME business customers: design a sustainability advisory toolkit containing a simple carbon footprint calculator for businesses with under 50 employees, a guide to CSRD applicability thresholds, a directory of green financing products, and a case study library of sustainable business transitions, and (4) design the metrics you will use to measure the effectiveness of each communication channel over 12 months. Format as a communication strategy with channel-specific content plans.","tags":["communications","stakeholder","retail-banking","customers","Austria"],"author":"AINOW","created":"2024-02-15T17:00:00Z","featured":false},

  {"id":"sus-86","title":"Sustainability Crisis Communications Playbook","prompt":"You are the Chief Communications Officer at a €2.4B Brazilian pulp and paper company that has just received an investigative journalism inquiry alleging that one of your eucalyptus plantation suppliers in Bahia state has illegally cleared 1,200 hectares of Caatinga dry forest habitat and displaced a Quilombola traditional community. You have 48 hours before the story publishes. Develop a crisis communications playbook for this situation and for future sustainability crises: (1) design the immediate 48-hour response protocol: who is on the crisis team, what is the first holding statement (acknowledging receipt of the allegations, confirming an urgent investigation, and not admitting liability), how do you verify the allegations using satellite imagery from Global Forest Watch and direct supplier contact within 24 hours, and what are the trigger points for a more substantive public statement, (2) design the stakeholder notification sequence: which stakeholders — investors, customers, employees, NGOs, regulatory authorities, and the affected community — should be notified in what order and through what channel, (3) design the remediation response for a confirmed violation: supplier suspension criteria, community engagement and remedy process aligned with UNGPs Pillar 3, forest restoration commitment, and supply chain audit trigger, and (4) develop a post-crisis disclosure process for your annual sustainability report and CDP submission. Format as a crisis communications playbook with a decision tree and a stakeholder communication matrix.","tags":["crisis-communications","deforestation","supply-chain","Brazil","UNGPs"],"author":"AINOW","created":"2024-02-15T17:05:00Z","featured":false},

  {"id":"sus-87","title":"Sustainability Strategy Internal Launch Campaign","prompt":"You are the Head of Internal Communications at a 9,500-employee Finnish telecommunications company that has just launched a new 5-year sustainability strategy with commitments to net zero Scope 1+2 by 2030, 50% reduction in Scope 3 Category 11 product energy consumption, and digital inclusion for 200,000 underserved Finns by 2028. Your CEO survey shows only 28% of employees feel informed about the company's sustainability direction. Design a 12-month internal launch campaign: (1) design the launch event series: a CEO-led all-employee webinar in month one, a sustainability strategy roadshow across your six main office locations with interactive Q&A in months two and three, and a sustainability challenge kickoff inviting teams to submit ideas for reducing their business unit's carbon footprint, (2) develop the internal communication content calendar for the year: monthly sustainability newsletters with real project updates and measurable milestones, quarterly sustainability data dashboard shared company-wide, bi-annual employee engagement surveys tracking sustainability awareness and personal commitment scores, and an annual sustainability celebration event recognising employee contributions, (3) design the manager enablement toolkit: a 60-minute team sustainability briefing pack, a set of ten FAQ cards for common employee questions about the strategy, and a guide on connecting individual job roles to the sustainability commitments, and (4) define the measurement framework: monthly internal communication effectiveness metrics, quarterly awareness survey tracking, and year-end target of 70% employee sustainability strategy awareness. Format as a campaign plan with a content calendar and a measurement dashboard.","tags":["internal-communications","employee-engagement","strategy-launch","net-zero","Finland"],"author":"AINOW","created":"2024-02-15T17:10:00Z","featured":false},

  {"id":"sus-88","title":"CSRD Implementation Roadmap for a Mid-Cap Company","prompt":"You are the Group CFO of a €1.9B Italian manufacturing company with 7,200 employees listed on Euronext Milan. Your company falls into the first wave of CSRD applicability for large public-interest entities, with your first CSRD-compliant sustainability statement due for the financial year 2025. Design the implementation roadmap: (1) assess the resource and capability requirements for CSRD compliance: how many additional FTEs are required in sustainability, finance, and legal functions; what external advisory and assurance fees should you budget; and what technology investment is needed for data collection, (2) build the 18-month project plan from double materiality assessment through to auditor sign-off, specifying the key milestones: double materiality assessment completion, ESRS gap analysis, data collection system implementation, draft sustainability statement, internal review, external assurance, and Board approval, (3) identify the top five implementation risks — data availability for Scope 3, ESRS datapoints with insufficient internal processes, assurance readiness, board sustainability expertise, and legal review complexity — and design a mitigation plan for each, and (4) design the CSRD steering committee structure including the roles of the CFO, CSO, General Counsel, and Head of Internal Audit. Format as an implementation roadmap with a project plan, a resource plan, and a risk register.","tags":["CSRD","implementation","compliance","Italy","roadmap"],"author":"AINOW","created":"2024-02-15T17:15:00Z","featured":true},

  {"id":"sus-89","title":"EU Taxonomy Non-Financial Company KPI Disclosure","prompt":"You are the Head of Sustainable Finance Reporting at a €3.8B French commercial property developer subject to CSRD and the EU Taxonomy Regulation. Your business activities — construction and development of commercial real estate, renovation of existing buildings, and acquisition and management of commercial property — all have potentially eligible activities under the EU Taxonomy Climate Change Mitigation and Climate Change Adaptation objectives. Design the full EU Taxonomy KPI disclosure: (1) screen each of your three main business activities against the EU Taxonomy Technical Screening Criteria: new construction (nearly Zero Energy Buildings requirement and lifecycle carbon assessment), major renovation (minimum 30% primary energy reduction criterion), and acquisition and ownership of buildings (EPC class A or top 15% of national building stock requirement), (2) apply the DNSH assessment for all five remaining objectives for each activity, focusing on the most challenging DNSH criteria — physical climate risk assessment for Climate Change Adaptation and biodiversity criteria for Pollution Prevention and Control, (3) calculate your Taxonomy KPIs: Taxonomy-eligible Turnover, Capex, and Opex as a percentage of total, then the subset that is Taxonomy-aligned after applying TSC and DNSH, and (4) prepare the disclosure tables required under the Taxonomy Disclosure Delegated Act including the template tables for non-financial undertakings. Format as a taxonomy disclosure package with completed disclosure tables.","tags":["EU-Taxonomy","real-estate","CSRD","climate-mitigation","disclosure"],"author":"AINOW","created":"2024-02-15T17:20:00Z","featured":false},

  {"id":"sus-90","title":"Carbon Border Adjustment Mechanism Compliance Strategy","prompt":"You are the Head of Trade Compliance and Sustainability at a €2.7B Austrian steel producer exporting 380,000 tonnes of steel products per year to the EU and importing 120,000 tonnes of iron ore and metallurgical coal from non-EU sources. The EU Carbon Border Adjustment Mechanism entered the transitional reporting phase in October 2023 and will impose full CBAM obligations from January 2026. Design your compliance strategy: (1) assess which of your steel product categories fall within the CBAM scope — currently including cement, aluminium, fertilisers, electricity, hydrogen, and selected iron and steel products at CN codes specified in Annex I of CBAM Regulation 2023/956 — and calculate the tonnes of embedded direct and indirect emissions subject to CBAM obligations for your 2026 export volume, (2) design the embedded emissions calculation methodology for your steel products in line with CBAM Implementing Regulation requirements, distinguishing between direct emissions from your own blast furnace and electric arc furnace processes and indirect emissions from purchased electricity, (3) model the financial liability under CBAM: estimated CBAM certificates required in 2026 at a projected EU ETS price of €80/tCO2e, and the impact on your export margins to EU customers, (4) assess the strategic options: can you reduce your CBAM liability through production decarbonisation, fuel switching, or re-routing exports to non-EU markets? Format as a compliance strategy document with a CBAM financial liability model and a strategic options analysis.","tags":["CBAM","carbon-border","steel","EU-ETS","trade-compliance"],"author":"AINOW","created":"2024-02-15T17:25:00Z","featured":false},

  {"id":"sus-91","title":"UK TCFD Mandatory Reporting Compliance Review","prompt":"You are the Company Secretary and Governance Director at a FTSE 350 UK asset manager with £42B in assets under management, subject to mandatory TCFD-aligned disclosure requirements under the FCA's ESG sourcebook (PS21/24). Your annual report due in four months must include full TCFD disclosures. Conduct a compliance review: (1) assess your current TCFD disclosures against the FCA's mandatory requirements for asset managers, identifying which of the 11 recommended TCFD disclosures are present, partially present, or missing — specifically for the strategy pillar assessing the resilience of your investment strategy under 1.5°C and 3°C scenarios, (2) evaluate the quality of your climate scenario analysis, assessing whether the scenarios used are credible (based on IPCC or IEA pathways), whether the time horizons extend to 2050, whether both transition and physical risks are covered, and whether asset-class-level impacts are quantified, (3) assess your firm-level TCFD disclosures (governance, risk management, metrics) against the FCA's expectation of entity-level versus product-level reporting, and (4) draft the enhanced climate risk section for your annual report that would achieve a 'significantly consistent' rating under CDP scoring. Format as a compliance gap analysis with a remediation plan and draft improved annual report language. [Paste your current sustainability report or ESG disclosure]","tags":["TCFD","FCA","asset-management","UK","climate-risk"],"author":"AINOW","created":"2024-02-15T17:30:00Z","featured":false},

  {"id":"sus-92","title":"EU Nature Restoration Law Business Impact Assessment","prompt":"You are the Regulatory Affairs and Sustainability Director at a €1.2B Dutch agri-business company growing vegetables, soft fruit, and bulb flowers across 24,000 hectares of owned and leased farmland in the Netherlands, Belgium, and Poland. The EU Nature Restoration Law (Regulation 2024/1991) requires member states to restore at least 20% of EU land and sea areas by 2030 and restore all degraded ecosystems by 2050, with mandatory farmland nature restoration measures affecting agricultural land. Conduct a business impact assessment: (1) map your 24,000 hectares of farmland against the EU Nature Restoration Law's agricultural ecosystem condition indicators — farmland bird index, grassland butterfly index, stock of organic carbon in mineral cropland soils, and share of agricultural land with high-diversity landscape features — and estimate what percentage of your land currently meets the baseline condition targets, (2) model the land productivity impact of achieving the required 10% high-diversity landscape features by 2030 — field margins, hedgerows, flower strips, and buffer zones — on your existing planted area and yield per hectare, (3) assess the financial impact: reduction in planted area, yield impact, and the potential revenue from agri-environment scheme payments under the post-2027 CAP for nature restoration activities, and (4) identify the best-performing nature restoration interventions for your specific crop types that minimise yield impact while maximising biodiversity indicator improvement. Format as a business impact assessment with a farmland condition gap analysis and a financial model.","tags":["EU-Nature-Restoration","agriculture","biodiversity","Netherlands","regulation"],"author":"AINOW","created":"2024-02-15T17:35:00Z","featured":false},

  {"id":"sus-93","title":"Corporate Sustainability Due Diligence Directive Gap Analysis","prompt":"You are the Legal and Compliance Director at a €4.3B Swedish retail group with 12,000 employees and a global sourcing operation spanning 68 countries. The EU Corporate Sustainability Due Diligence Directive (CS3D) will require companies of your size to conduct human rights and environmental due diligence across their full value chain, set up grievance mechanisms, and adopt a transition plan aligned with the Paris Agreement. Conduct a CS3D gap analysis: (1) assess your current human rights and environmental due diligence processes against the CS3D requirements across the six due diligence steps — integrating due diligence into policies, identifying actual and potential adverse impacts, preventing potential impacts, bringing actual impacts to an end, monitoring, and communicating — and rate each step as compliant, partially compliant, or not compliant, (2) identify the three most significant gaps between your current processes and CS3D requirements, with specific reference to your supply chain in high-risk countries (Bangladesh, Cambodia, and Vietnam for garments; Brazil and Indonesia for food), (3) estimate the resource requirement and timeline to close the identified gaps before the CS3D transposition deadline, and (4) design the CS3D-compliant grievance mechanism covering accessibility for workers in Tier 2 and Tier 3 supply chains, confidentiality protections, case tracking, and annual reporting. Format as a gap analysis report with a remediation roadmap and a grievance mechanism design specification. [Describe your organization and current sustainability situation]","tags":["CS3D","due-diligence","human-rights","compliance","Sweden"],"author":"AINOW","created":"2024-02-15T17:40:00Z","featured":false},

  {"id":"sus-94","title":"EU Emissions Trading System Strategic Management","prompt":"You are the Carbon Markets and Regulatory Affairs Manager at a €2.1B German cement manufacturer operating three kiln lines at two sites, producing 3.8 million tonnes of clinker per year with associated Scope 1 emissions of 3.2 million tCO2e — making you one of Germany's 50 largest ETS installation operators. Your free allocation is decreasing under Phase 4 rules and your net ETS liability is growing. Design an ETS strategic management programme: (1) model your free allocation trajectory from 2025 to 2030 under the ETS Phase 4 benchmark declining curve, and calculate your projected annual shortfall in tCO2e and financial liability at the ETS forward price curve of €65/tCO2e today escalating to €130/tCO2e by 2030, (2) design a hedging strategy for your ETS allowance procurement: how many allowances to purchase in forward markets versus spot market, at what carbon price triggers to increase or reduce forward purchases, and how to account for EUA allowances under IFRS (IAS 37 and IAS 38), (3) assess the CCUS (carbon capture, utilisation, and storage) technology options for cement process emissions — specifically post-combustion amine scrubbing and oxyfuel combustion — including capital cost estimates, capture efficiency, and the timeline to first commercial deployment in the EU cement sector, and (4) evaluate the Innovation Fund application potential for a CCUS pilot at one of your kilns. Format as an ETS management strategy with a financial liability model and a CCUS technology assessment.","tags":["EU-ETS","carbon-markets","cement","CCUS","Germany"],"author":"AINOW","created":"2024-02-15T17:45:00Z","featured":false},

  {"id":"sus-95","title":"UK Net Zero Buildings Regulation Compliance Strategy","prompt":"You are the Technical Director and Sustainability Lead at a UK property developer completing 2,200 new homes per year across the North West and Midlands. The Future Homes Standard, mandatory from 2025, requires new homes to produce 75–80% less CO2 than homes built under 2013 Part L regulations, effectively ending gas boiler installations in new homes. The requirement for zero-carbon ready homes creates significant design, cost, and supply chain challenges. Design your compliance strategy: (1) assess the two main compliance pathways under the Future Homes Standard — the fabric-first approach with high insulation U-values combined with heat pump, versus the fabric standard approach with enhanced air tightness and MVHR — and model the capital cost premium per unit, the SAP energy rating achievable, and the heat demand in kWh/m2/year for a representative 3-bedroom semi-detached house type, (2) design the supply chain readiness programme to ensure your heat pump installer base, plumber and electrician workforce, and air-tightness testing capacity can scale to your 2,200 homes per year build rate by January 2025, (3) calculate the impact on your Help-to-Buy and shared ownership customers: will the higher-fabric-cost homes require higher selling prices, and how does the lower energy bill offset this for buyers over a 5-year and 10-year horizon, and (4) assess the embodied carbon implications of the fabric-first versus standard pathway, using the RICS Whole Life Carbon Assessment framework. Format as a technical compliance strategy with a unit cost comparison model and a supply chain readiness plan.","tags":["Future-Homes-Standard","net-zero-buildings","UK","heat-pump","embodied-carbon"],"author":"AINOW","created":"2024-02-15T17:50:00Z","featured":false},

  {"id":"sus-96","title":"US State Carbon Pricing and Voluntary Market Navigation","prompt":"You are the VP of Environmental Strategy at a $6.2B US food and beverage manufacturer with production facilities in California (subject to the California Cap-and-Trade Program), Washington State (subject to the Washington Cap and Invest Program), and eight other states where voluntary action is currently the only carbon pricing mechanism. Your annual Scope 1 emissions are 320,000 tCO2e. Design a carbon pricing strategy: (1) assess your compliance obligations under the California and Washington programs: calculate the required allowances for your facilities in each state, the current compliance instrument prices (California CCAs and Washington Program allowances), and the total annual compliance cost, (2) design the allowance procurement strategy for both compliance programs: how to balance free allocations, market purchases, and offset credits (ARB-eligible offsets in California and CRT eligible credits in Washington), and how to manage price volatility risk through forward purchasing, (3) evaluate whether your remaining eight-state facilities should voluntarily adopt an internal carbon price and at what level — assess the strategic value of voluntary internal carbon pricing for your SBTi commitment, your CDP score improvement, and your readiness for potential federal carbon pricing, and (4) model the total carbon cost trajectory from 2025 to 2035 under three price scenarios: low (following current state program forward curves), central (adding voluntary federal pricing at $40/tCO2e from 2028), and high (aligned with the IMF optimal carbon price pathway). Format as a carbon pricing strategy with a compliance cost model and a price scenario analysis.","tags":["carbon-pricing","California-cap-and-trade","US","compliance","strategy"],"author":"AINOW","created":"2024-02-15T17:55:00Z","featured":false},

  {"id":"sus-97","title":"Modern Slavery Act Compliance and Transparency Statement","prompt":"You are the Chief Ethics Officer at a £3.8B UK food manufacturing and retail group with direct sourcing from over 60 countries including high-risk jurisdictions for forced labour: Thailand (seafood), Malaysia (palm oil and rubber), and Xinjiang region sourcing risk in your cotton-containing textiles range. Your Modern Slavery Act Section 54 transparency statement is due for Board approval and Companies House filing. Design a best-practice transparency statement and the underlying due diligence programme: (1) structure the transparency statement covering all six MSA Section 54 requirements — organisation structure and supply chains, policies in relation to slavery and human trafficking, due diligence processes, risk assessment and management, KPIs for effectiveness of steps taken, and training — at a level of detail that would achieve a Grade A rating under the Business and Human Rights Resource Centre's MSA assessment methodology, (2) design the enhanced due diligence process for your three highest-risk supply chains, including the specific assessment tools — Sedex SMETA audits, worker voice surveys via Laborlink, and satellite-based monitoring for deforestation-linked forced labour risk — and the frequency and coverage targets, (3) design the Xinjiang sourcing policy, including the due diligence steps required to demonstrate compliance with the US Uyghur Forced Labor Prevention Act for any products sold in the US market, and (4) design the modern slavery grievance mechanism and worker helpline accessible to workers in Thai seafood processing facilities. Format as a draft MSA transparency statement with a due diligence programme summary.","tags":["Modern-Slavery-Act","human-rights","supply-chain","UK","forced-labour"],"author":"AINOW","created":"2024-02-15T18:00:00Z","featured":false},

  {"id":"sus-98","title":"GHG Protocol Scope 3 Standard Methodology Selection","prompt":"You are the Carbon Accounting Lead at a €2.8B Swiss diversified financial services company providing retail banking, asset management, and insurance services. You are building your first comprehensive Scope 3 GHG inventory covering all 15 categories of the GHG Protocol Corporate Value Chain Standard. Given the complexity of financial services Scope 3 — where the most material category is financed emissions (Category 15) rather than operational emissions — design the methodology selection and implementation plan: (1) assess the materiality of all 15 Scope 3 categories for your business model, identifying financed emissions via PCAF, business travel (Category 6), employee commuting (Category 7), purchased goods and services for your head office operations (Category 1), and the upstream emissions of your insurance underwriting portfolio (emerging under the PCAF Insurance standard), (2) select the appropriate calculation methodology for each of your top five categories, specifying whether you will use spend-based, activity-based, supplier-specific, or PCAF asset-class-specific methods, (3) design the data collection process for your PCAF Category 15 financed emissions calculation, specifying the data required from each asset class in your €24B lending and investment portfolio, the data sources, and the PCAF Data Quality Score target for each asset class, and (4) estimate the total Scope 3 inventory for your first year, with confidence ranges reflecting data quality, and identify the three highest-priority areas for improving data quality. Format as a methodology note with a category-by-category approach table and a data quality improvement roadmap.","tags":["scope-3","GHG-protocol","PCAF","financial-services","methodology"],"author":"AINOW","created":"2024-02-15T18:05:00Z","featured":false},

  {"id":"sus-99","title":"Product Environmental Footprint EU Compliance Strategy","prompt":"You are the Regulatory Compliance Director at a €1.6B Italian consumer electronics company manufacturing laptops, tablets, and smartphones sold across the EU. The European Commission's Product Environmental Footprint methodology is being incorporated into the EU Green Claims Directive and the Digital Product Passport under ESPR, requiring you to calculate and disclose the PEF of your product portfolio. Design your PEF compliance strategy: (1) conduct a PEF study for your best-selling laptop model using the PEF Category Rules for ICT Equipment, covering the 16 environmental impact categories including climate change (kgCO2e), resource use fossils (MJ), water use (m3 world eq.), and land use (Pt) — across the full lifecycle from raw material extraction through manufacturing, use phase (4-year assumed use), and end-of-life, (2) identify the three lifecycle stages with the highest environmental impact across the 16 categories — typically materials production for mineral and metal use, use-phase energy consumption for climate change, and end-of-life for hazardous substance categories — and design a product improvement roadmap targeting the most material impacts, (3) assess the data quality requirements for a PEF study compliant with the PEF Method and the ICT PEF Category Rules, including the secondary data sources permitted versus the primary data collection required from your Taiwanese contract manufacturers, and (4) design the communication of PEF results to B2B procurement customers who are incorporating PEF data into their sustainable procurement criteria. Format as a PEF compliance strategy with a lifecycle hotspot analysis and a data collection plan.","tags":["PEF","product-footprint","EU","ICT","lifecycle-assessment"],"author":"AINOW","created":"2024-02-15T18:10:00Z","featured":false},

  {"id":"sus-100","title":"2035 Sustainability Regulatory Horizon Scan and Strategic Preparation","prompt":"You are the Chief Sustainability Officer and Group General Counsel at a €5.8B pan-European industrial group with operations in 18 EU member states and exports to 45 countries globally, covering steel fabrication, speciality coatings, and logistics services. Your Board has asked you to prepare a 10-year regulatory horizon scan so that sustainability compliance costs and opportunities can be incorporated into the next strategic plan cycle (2026–2035). Design the horizon scan: (1) map the top 20 sustainability regulations that will materially affect your business between 2025 and 2035, including the CSRD phased applicability, CS3D value chain obligations, CBAM full implementation for steel products, EU Taxonomy expanding scope to all companies, EU Deforestation Regulation for your packaging wood inputs, the revised EU ETS Phase 4 and Phase 5 rules, the EU Nature Restoration Law farmland requirements affecting your logistics depot land, the Product Environmental Footprint mandatory disclosure rules, the Digital Product Passport for your steel and coatings products, and any anticipated carbon pricing developments in the US and UK, (2) for each of the top 20 regulations, assess: the compliance deadline, the estimated annual compliance cost or revenue impact, and the strategic opportunity or threat it represents, (3) identify the five regulations requiring the largest internal capability investments — specifically data systems, legal expertise, scientific expertise, supply chain management, and finance — and design a shared capability building programme that leverages common investments across multiple regulatory requirements, and (4) produce the Board-level regulatory risk register with likelihood and financial impact scoring, prioritised mitigation actions, and an early warning indicator system for regulatory developments that could accelerate or change the current trajectory. Format as a regulatory horizon scan report with a regulatory risk register and a capability investment plan.","tags":["regulation","horizon-scan","strategy","EU","compliance"],"author":"AINOW","created":"2024-02-15T18:15:00Z","featured":false}

];
  __exports.sustainabilityPrompts = sustainabilityPrompts;
})();
